import {OrganiserReports} from './CourseSharing.jsx';
import React,{useEffect,useRef,useState} from 'react';
import {workshopRequest} from './client.js';
import {formatName} from './programme.js';
import {PLAN_TEMPLATES,coursePlanRoute} from './course-plan.js';
import {CourseDelivery} from './CourseDelivery.jsx';
import './course-planner.css';
export function CoursePlanner({course,data,client,onSave,onPrepare,onStart,onReload}){
 const [open,setOpen]=useState(false),[result,setResult]=useState(null),[jobId,setJobId]=useState(''),[goal,setGoal]=useState(course.goal||''),[sources,setSources]=useState(null),[selected,setSelected]=useState([]),[confirmed,setConfirmed]=useState(false),[reviewed,setReviewed]=useState(false),[editing,setEditing]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[drafting,setDrafting]=useState(false);
 const [deliveryVersion,setDeliveryVersion]=useState(0);
 const life=useRef(0),key=useRef(null),identity=client.journal.user.id;
 const active=()=>identity===client.journal.user?.id;
 const job=result?.jobs.find(j=>j.id===(jobId||course.plan?.id))||result?.jobs[0];
 const linked=job?.status==='approved'&&course.plan?.id===job.id&&course.plan.hash===job.draftHash,usable=linked&&!job.issues.length;
 const canonicalItems=client.items.map(item=>({...item,sourceHash:data.chapters.find(c=>c.id===item.jobId&&c.status==='published')?.hash}));
 const route=usable?coursePlanRoute(job.draft,course.plan.links,{...client,items:canonicalItems}):null;
 async function request(body){const epoch=life.current;const r=await client.journal.request('course-plan'+(!body?'?'+new URLSearchParams({courseId:course.id}):''),body?{...body,courseId:course.id}:undefined);if(epoch!==life.current||!active())throw Error('This course view changed. Reopen it to continue.');setResult(r);if(r.jobId)setJobId(r.jobId);return r;}
 async function run(fn){if(busy)return;setBusy(true);setError('');try{await fn()}catch(e){if(active())setError(e.message)}finally{if(active())setBusy(false)}}
 useEffect(()=>{return()=>{life.current++}},[]);
 useEffect(()=>{if(open)void run(()=>request());},[open]);
 useEffect(()=>{
  if(!open||!job||!['starting','running'].includes(job.status))return;
  const timer=setTimeout(()=>{void request({action:'check',id:job.id}).catch(e=>setError(e.message))},5000);return()=>clearTimeout(timer);
 },[open,job?.id,job?.status,result]);
 async function collect(){
  const bindings=[...new Map(course.topics.flatMap(t=>t.resources).map(r=>[r.id,r])).values()];if(bindings.length>12)throw Error('The planner handles twelve linked sources per course. Split this course before planning.');
  const ready=bindings.filter(v=>data.resources.some(r=>r.id===v.id&&r.checksum===v.checksum&&r.status==='reviewed'));if(!ready.length)throw Error('Review and link source material before preparing a plan.');
  const rows=[];for(const r of ready){const d=await workshopRequest('resources/'+encodeURIComponent(r.id));if(!active())return;rows.push(d.resource)}setSources(rows);setSelected([]);setConfirmed(false);setDrafting(true);setEditing(null);key.current=null;
 }
 const passages=sources?.flatMap(r=>r.units.map(u=>({...u,resourceId:r.id})))||[],chosen=passages.filter(u=>selected.includes(u.id)),chars=chosen.reduce((n,u)=>n+u.excerpt.length,0);
 function toggle(id){setSelected(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id]);setConfirmed(false);key.current=null;}
 const update=(i,field,value)=>{setEditing(d=>({...d,steps:d.steps.map((s,n)=>n===i?{...s,[field]:value}:s)}));setReviewed(false)};
 return <section className="course-planner" aria-label="Course learning route"><div className="cp-heading"><div><h3>A route through {course.title}</h3><p>Turn reviewed material into connected objectives, then prepare activities for each step.</p></div><button disabled={busy} onClick={()=>setOpen(!open)} aria-expanded={open}>{open?'Close course route':course.plan?'Open course route':'Plan this course'}</button></div>
 {open&&<><div role="status" aria-live="polite">{busy&&<p>Saving or loading your course route…</p>}{error&&<p className="message error" role="alert">{error}</p>}</div><div className="cp-toolbar">{course.plan&&<button disabled={busy} onClick={()=>run(()=>onSave({type:'unlink-plan',courseId:course.id}))}>Remove route link</button>}<button disabled={busy} onClick={()=>run(collect)}>Prepare a new plan</button><button disabled={busy} onClick={()=>run(async()=>{await request();await client.refresh()})}>Refresh saved plans and progress</button>{result?.jobs.length>0&&<label>Saved plan<select value={job?.id||''} onChange={e=>{setJobId(e.target.value);setEditing(null);setReviewed(false);setDrafting(false)}}>{result.jobs.map(j=><option key={j.id} value={j.id}>{j.draft?.title||'Plan request'} — {j.status}</option>)}</select></label>}</div>
 {drafting&&sources&&<form className="cp-evidence" onSubmit={e=>{e.preventDefault();void run(async()=>{const fingerprint=JSON.stringify({goal,selected});if(!key.current||key.current.fingerprint!==fingerprint)key.current={fingerprint,id:crypto.randomUUID()};const r=await request({action:'create',goal,evidenceIds:selected,confirmed,requestKey:key.current.id});setDrafting(false);setReviewed(false);await request({action:'run',id:r.jobId})})}}><h4>Choose the evidence the AI will read</h4><label>Course or exam goal<textarea maxLength={1200} required minLength={10} value={goal} onChange={e=>{setGoal(e.target.value);setConfirmed(false);key.current=null}}/></label><p>Your saved starting point, context and interests help shape the proposal. They do not determine your ability or a fixed learning style.</p><p className="cp-coverage">{selected.length} of {passages.length} reviewed passages selected · {chars.toLocaleString()} / 32,000 characters. {passages.length-selected.length} passages will not be sent. Select up to 24.</p><div className="cp-passages">{sources.map(r=><details key={r.id} open={sources.length===1}><summary>{r.title} — {r.units.length} passages</summary>{r.units.map(u=><label className="cp-passage" key={u.id}><input type="checkbox" checked={selected.includes(u.id)} disabled={busy||!selected.includes(u.id)&&(selected.length>=24||chars+u.excerpt.length>32000)} onChange={()=>toggle(u.id)}/><span><b>{u.locator}</b><span>{u.excerpt}</span></span></label>)}</details>)}</div><label className="check"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I have checked these passages and the intended scope. Omitted material is not covered by this request.</label><button className="primary" disabled={busy||!confirmed||!selected.length||chars>32000}>Ask the AI for a course plan</button><button type="button" onClick={()=>setDrafting(false)}>Cancel</button><p>One AI request uses the generation allowance. Editing and approving the saved plan is free.</p></form>}
 {job&&!drafting&&<><div className="cp-plan-heading"><span>{job.status==='approved'?'Reviewed plan':job.status==='review'?'Teaching review':'Saved request'} · {job.model}</span><h4>{job.draft?.title||'Preparing your course route'}</h4><p>{job.draft?.summary||'This request is saved. Leave and return to check the same response.'}</p>{job.context?.coverage?<p className="cp-coverage">The AI received {job.context.coverage.selectedPassages} of {job.context.coverage.totalPassages} reviewed passages; {job.context.coverage.omittedPassages} were omitted. {job.context.coverage.unreviewedOrMissingSources||0} linked sources were unavailable or unreviewed. Exact citations verify provenance, not whether every claim is supported.</p>:<p className="cp-coverage">Coverage counts are unavailable for this saved plan. Review its cited evidence before assigning.</p>}</div>
 {job.context?.profile&&<details className="cp-context"><summary>Personal context used for this plan</summary><p>{job.context.profile.stage} · {job.context.profile.level}</p><p>{job.context.profile.context||'No additional context supplied.'}</p><p>Interests: {job.context.profile.interests.join(', ')||'None selected'}. Areas to practise: {job.context.profile.struggles||'None specified'}.</p><p>Exam focus: {job.context.profile.exam||'None specified'}. Time available: {job.context.profile.minutes} minutes. This is the profile snapshot from the request; changing your profile does not silently regenerate this plan.</p></details>}
 {job.error&&<p role="alert">{job.error}</p>}{job.issues.map(x=><p className="message error" key={x}>{x}</p>)}
 {['queued','starting','running','interrupted','failed'].includes(job.status)&&<button disabled={busy} onClick={()=>run(()=>request({action:job.status==='queued'?'run':'check',id:job.id}))}>{job.status==='queued'?'Run saved request':'Check saved response'}</button>}
 {job.draft&&<>{job.draft.gaps.length>0&&<aside className="cp-gaps"><h4>Outside this plan’s evidence</h4><ul>{job.draft.gaps.map((g,i)=><li key={i}>{g}</li>)}</ul><p>Approval accepts this limited scope. Add evidence and prepare a new plan to cover these gaps.</p></aside>}
 {linked&&!editing&&client.access?.manages&&<CourseDelivery key={identity+course.id+job.id+job.draftHash+JSON.stringify(course.plan.links)+JSON.stringify(data.chapters)} course={course} job={job} data={data} client={client} onAssigned={()=>setDeliveryVersion(v=>v+1)} onReload={async()=>{await onReload();await request();await client.refresh()}}/>}
 {client.access?.manages&&<OrganiserReports course={course} client={client} revision={deliveryVersion}/>}
 {route?.next&&<div className="cp-next"><b>Suggested next step: {route.next.step.objective}</b><p>{route.next.reason}</p><small>Based on your saved practice and help, not game scores. You can choose any objective. This is not a grade or mastery estimate.</small></div>}
 {editing&&<label>Plan title<input value={editing.title} maxLength={120} onChange={e=>setEditing({...editing,title:e.target.value})}/></label>}
 <ol className="cp-objectives">{(editing||job.draft).steps.map((step,i)=>{const row=route?.rows.find(r=>r.step.id===step.id);return <li key={step.id}><div className="cp-step"><span className="cp-number">{i+1}</span><div><span>{job.context.topics.find(t=>t.id===step.topicId)?.title}</span>{editing?<><label>Objective {i+1}<textarea maxLength={240} value={step.objective} onChange={e=>update(i,'objective',e.target.value)}/></label><label>Why this activity?<textarea maxLength={500} value={step.rationale} onChange={e=>update(i,'rationale',e.target.value)}/></label><label>Activity format<select value={step.template} onChange={e=>update(i,'template',e.target.value)}>{PLAN_TEMPLATES.map(t=><option key={t} value={t}>{formatName(t)}</option>)}</select></label><fieldset><legend>Suggested preparation</legend>{editing.steps.slice(0,i).map(s=><label className="check" key={s.id}><input type="checkbox" checked={step.prerequisites.includes(s.id)} onChange={e=>update(i,'prerequisites',e.target.checked?[...step.prerequisites,s.id]:step.prerequisites.filter(x=>x!==s.id))}/>{s.objective}</label>)}{i===0&&<p>This is the starting objective.</p>}</fieldset></>:<><h4>{step.objective}</h4><p>{step.rationale}</p><p><b>{formatName(step.template)}</b> · {step.prerequisites.length?'Suggested preparation: '+step.prerequisites.map(id=>job.draft.steps.find(s=>s.id===id)?.objective).join('; '):'A starting point'}</p></>}
 <details><summary>Check {step.sourceRefs.length} supporting passages</summary>{step.sourceRefs.map(id=>{const s=job.context.evidence.find(e=>e.id===id);return <blockquote key={id}><p>{s.excerpt}</p><cite>{s.title} — {s.locator}</cite></blockquote>})}</details>
 {usable&&!editing&&<div className="cp-actions"><p>{row.reason}</p>{row.item?<button className="primary" disabled={busy} onClick={()=>run(()=>onStart(row.item,true,step.objective))}>{row.unit?'Continue learning':'Start learning'}</button>:<button disabled={busy} onClick={()=>onPrepare(step,job)}>Prepare this activity</button>}</div>}</div></div></li>})}</ol>
 {job.status==='review'&&!job.issues.length&&<div className="cp-review">{editing?<><button className="primary" disabled={busy} onClick={()=>run(async()=>{await request({action:'edit',id:job.id,draftHash:job.draftHash,draft:editing});setEditing(null);setReviewed(false)})}>Save free edits</button><button onClick={()=>setEditing(null)}>Discard edits</button></>:<><button onClick={()=>setEditing(structuredClone(job.draft))}>Edit objectives and preparation</button><label className="check"><input type="checkbox" checked={reviewed} onChange={e=>setReviewed(e.target.checked)}/>I checked factual support, objective scope, suggested preparation and the gaps listed above.</label><button className="primary" disabled={busy||!reviewed||!job.draft.steps.length} onClick={()=>run(()=>request({action:'approve',id:job.id,draftHash:job.draftHash,confirmed:true}))}>Approve this plan</button></>}</div>}
 {job.status==='approved'&&!linked&&!job.issues.length&&<button className="primary" disabled={busy} onClick={()=>run(()=>onSave({type:'link-plan',courseId:course.id,id:job.id,hash:job.draftHash}))}>Use this reviewed course route</button>}
 </>}
 </>}
 {result&&course.plan&&!result.jobs.some(j=>j.id===course.plan.id)&&<p className="message error">This saved route is no longer available. Remove its route link to clear the notebook. Sources, chapters and progress stay saved; no AI request is needed.</p>}
 {!job&&!drafting&&!busy&&<p>Prepare a plan from the reviewed sources linked across this course. The AI proposes objectives; you decide which route to approve.</p>}
 </>}
 </section>;
}
