import {SearchSuggestions} from './SearchSuggestions.jsx';
import React,{useEffect,useRef,useState} from 'react';
import {readLibrary} from '../resource-client.js';
import {currentEvidence,evidenceChoice,retrievalQuery} from '../passage-ranking.js';
import './evidence-finder.css';

export function EvidenceFinder({sources,onPrepare,onLink,goal='',disabled=false}){
 const [draft,setDraft]=useState(''),[related,setRelated]=useState(''),[scope,setScope]=useState('library'),[query,setQuery]=useState(null),[page,setPage]=useState(null),[history,setHistory]=useState([]),[cursor,setCursor]=useState(null),[selected,setSelected]=useState([]),[busy,setBusy]=useState(false),[error,setError]=useState(''),[chapterGoal,setChapterGoal]=useState(goal),[preview,setPreview]=useState(null);
 const previewHeading=useRef(null),readTrigger=useRef(null);
 useEffect(()=>{if(preview)previewHeading.current?.focus()},[preview]);
 const sequence=useRef(0),life=useRef(true),snapshot=useRef(null);
 useEffect(()=>{life.current=true;return()=>{life.current=false;sequence.current++}},[]);
 const characters=selected.reduce((n,p)=>n+p.excerpt.length,0),sourceCount=new Set(selected.map(p=>p.resourceId)).size;
 async function search(q,c=null,h=[]){
  const turn=++sequence.current;setBusy(true);setError('');setPage(null);
  try{const params=new URLSearchParams({...q,order:'relevance',status:'reviewed'});if(c)params.set('cursor',c);const p=await readLibrary('search?'+params);if(!life.current||turn!==sequence.current)return;
   if(snapshot.current&&snapshot.current!==p.snapshot)setError('Your library changed. Selected passages are kept and will be checked before use.');snapshot.current=p.snapshot;setPage(p);setQuery(q);setCursor(c);setHistory(h);
  }catch(e){if(life.current&&turn===sequence.current){setError(e.message+' Your selected passages are kept and will be checked before use.');snapshot.current=null}}
  finally{if(life.current&&turn===sequence.current)setBusy(false)}
 }
 function submit(e){e.preventDefault();try{retrievalQuery(draft,related)}catch(e){setError(e.message);return}const q={q:draft.trim(),related,...(scope==='topic'?{ids:sources.map(s=>s.id).join(',')}:{})};if(JSON.stringify(q)!==JSON.stringify(query))setSelected([]);setPreview(null);snapshot.current=null;void search(q);if(!chapterGoal)setChapterGoal(draft.trim())}
 const dirty=query&&(query.q!==draft.trim()||query.related!==related||Boolean(query.ids)!==(scope==='topic'));
 async function readSource(id,trigger){
  if(busy||disabled)return;readTrigger.current=trigger;setBusy(true);setError('');
  try{const r=(await readLibrary('resources/'+encodeURIComponent(id))).resource;if(life.current)setPreview(r)}catch(e){if(life.current)setError(e.message)}finally{if(life.current)setBusy(false)}
 }
 async function prepare(){
  if(busy||disabled)return;setBusy(true);setError('');
  try{const rows=[];for(const id of new Set(selected.map(p=>p.resourceId))){rows.push((await readLibrary('resources/'+encodeURIComponent(id))).resource);if(!life.current)return}
   const evidence=currentEvidence(selected,rows);if(life.current)onPrepare({kind:'plan',goal:chapterGoal.trim(),evidence});
  }catch(e){if(life.current)setError(e.message)}finally{if(life.current)setBusy(false)}
 }
 return <section className="evidence-finder" aria-label="Find learning evidence"><div className="ef-heading"><h3>Find the evidence for your next chapter</h3><p>Search every reviewed passage in your library, then choose the material you want the chapter to use.</p></div>
 <form className="ef-query" onSubmit={submit}><label>Ideas or terms to find<input disabled={busy} type="search" maxLength={240} required value={draft} onChange={e=>setDraft(e.target.value)} placeholder="For example, energy food webs populations"/></label><label>Search in<select disabled={busy} value={scope} onChange={e=>{setScope(e.target.value);setPreview(null);setPage(null);setSelected([]);setQuery(null);sequence.current++;setBusy(false)}}><option value="library">My reviewed library</option><option value="topic">Reviewed topic sources</option></select></label><button disabled={busy||disabled||scope==='topic'&&!sources.length}>Find relevant passages</button><details className="ef-alternatives"><summary>Add alternative words or phrases</summary><p>Add synonyms, spellings or translations, one phrase per line. These broaden word matching; they do not establish that two ideas mean the same thing.</p><label>Alternative phrases<textarea disabled={busy} rows={3} maxLength={488} value={related} onChange={e=>setRelated(e.target.value)} placeholder={'For example:\nvaporisation\nwater changes to gas'}/></label><small>Up to eight phrases. Search and edits use no AI allowance.</small></details><SearchSuggestions query={draft} onUse={setRelated}/></form>
 <div aria-live="polite">{busy&&<p role="status">Checking your reviewed sources…</p>}{error&&<p role="alert" className="message error">{error}</p>}{dirty&&<p className="ef-note">Search again to apply your edited terms. The results below belong to “{query.q}”.</p>}</div>
 {preview&&<aside className="ef-source" aria-label="Whole source preview"><h4 ref={previewHeading} tabIndex={-1}>{preview.title}</h4><p>{preview.status==='reviewed'?'Reviewed source':'This source needs review before it can be used.'} · {preview.units.length} passages. Your evidence selection stays below.</p><div className="ef-source-text" tabIndex={0} aria-label="Source passages">{preview.units.map(u=><section key={u.id}><h5>{u.locator}</h5><p>{u.excerpt}</p></section>)}</div><button type="button" onClick={()=>{setPreview(null);readTrigger.current?.focus()}}>Close source preview</button></aside>}
 {page&&<><div className="ef-coverage"><b>{page.totalMatches} matching passages for “{query.q}”</b><p>Searched all {page.passagesScanned.toLocaleString()} passages in {page.scanned} reviewed sources. {page.excludedSources} unreviewed sources excluded.</p><p>Ranked by word and phrase relevance across this search. A match is a place to look, not proof that the goal is supported.</p>{page.notFound.length>0&&<p className="ef-gap"><b>Search words not found:</b> {page.notFound.join(', ')}. Try alternative wording or add source material.</p>}{page.relatedNotFound.length>0&&<p>Alternative phrases not found: {page.relatedNotFound.join(', ')}.</p>}</div>
 <ol className="ef-results" start={page.offset+1}>{page.results.map(p=>{const checked=selected.some(s=>s.resourceId===p.resourceId&&s.id===p.id);return <li key={p.resourceId+p.id}><div className="ef-result-heading"><div><h4>{p.title}</h4><span>{p.locator}</span></div><label className="ef-select"><input type="checkbox" checked={checked} disabled={busy||disabled} aria-label={'Select '+p.title+' '+p.locator} onChange={()=>{try{setSelected(evidenceChoice(selected,p));setError('')}catch(e){setError(e.message)}}}/>Use passage</label></div><blockquote>{p.excerpt}</blockquote><p className="ef-match">{p.matched.length>0&&<>Search words: {p.matched.join(', ')}. </>}{p.relatedMatched.length>0&&<>Alternative phrases: {p.relatedMatched.join(', ')}.</>}</p><div className="ef-result-actions"><button type="button" disabled={busy||disabled} onClick={e=>readSource(p.resourceId,e.currentTarget)}>Read whole source</button>{onLink&&<button type="button" disabled={busy||disabled||sources.some(s=>s.id===p.resourceId&&s.checksum===p.checksum)} onClick={()=>onLink({id:p.resourceId,checksum:p.checksum})}>{sources.some(s=>s.id===p.resourceId&&s.checksum===p.checksum)?'Linked to this topic':'Link source to topic'}</button>}</div></li>})}</ol>
 {!page.results.length&&<p className="ef-empty">No reviewed passage matched this wording. Try a source’s terminology, add alternative phrases, or upload and review material for this goal.</p>}
 <div className="library-page-actions"><button type="button" disabled={busy||!history.length} onClick={()=>search(query,history.at(-1),history.slice(0,-1))}>Previous results</button><span>{page.totalMatches?`${page.offset+1}–${Math.min(page.offset+page.results.length,page.totalMatches)} of ${page.totalMatches}`:'No results'}</span><button type="button" disabled={busy||!page.nextCursor} onClick={()=>search(query,page.nextCursor,[...history,cursor])}>More results</button></div></>}
 {selected.length>0&&<aside className="ef-selection" aria-label="Selected chapter evidence"><h4>Evidence to take into your chapter</h4><p>{selected.length} / 12 passages from {sourceCount} / 3 sources · {characters.toLocaleString()} / 18,000 characters. Selections stay with you between result pages.</p><ul>{selected.map(p=><li key={p.resourceId+p.id}><span>{p.title} — {p.locator}</span><button type="button" disabled={busy} aria-label={'Remove '+p.title+' '+p.locator} onClick={()=>setSelected(selected.filter(s=>!(s.resourceId===p.resourceId&&s.id===p.id)))}>Remove</button></li>)}</ul><label>Chapter learning goal<textarea disabled={busy} rows={2} maxLength={1200} value={chapterGoal} onChange={e=>setChapterGoal(e.target.value)}/></label><button className="primary" disabled={busy||disabled||chapterGoal.trim().length<10} onClick={prepare}>Review selected evidence</button><p>The next screen checks these exact passages before an AI request. Search does not generate or publish a chapter.</p></aside>}
 </section>;
}
