import {LearnerCourses,LearnerAssigned,OrganiserOverview} from './CourseSharing.jsx';
import React,{useEffect,useState,useRef} from 'react';
import {canPrepare,pilotRequest} from './client.js';
import {LibraryPicker} from './SourceLibrary.jsx';
import {EvidenceFinder} from './EvidenceFinder.jsx';
import {CoursePlanner} from './CoursePlanner.jsx';
import {ChapterWorkshop} from './ChapterWorkshop.jsx';
import {formatName,activitiesOf,unitKey,contentOf} from './programme.js';
import {chapterCopyLabel} from '../chapter-content.js';
import './courses.css';

// Learners who don't prepare courses see one merged Assigned list (see CourseSharing.jsx).
export function AssignmentShelf({client,onStart,busy=false,page=false}){return <LearnerAssigned client={client} onStart={onStart} busy={busy} page={page}/>}
export function CourseWorkspace({client,onStart,onBrowse}){
 const [data,setData]=useState(null),[courseId,setCourseId]=useState(''),[topicId,setTopicId]=useState(''),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[form,setForm]=useState(null),[workshop,setWorkshop]=useState(null),[confirm,setConfirm]=useState(null),[delivery,setDelivery]=useState(null);
 const author=canPrepare(client),loadSequence=useRef(0);
 const account=client.journal.user?.id||'';
 const course=data?.state.courses.find(c=>c.id===courseId)||data?.state.courses[0],topic=course?.topics.find(t=>t.id===topicId)||course?.topics[0];
 async function load(){const sequence=++loadSequence.current,identity=client.journal.user?.id;const next=await client.journal.request('courses');if(sequence===loadSequence.current&&identity===client.journal.user?.id)setData(next);return next;}
 useEffect(()=>{let active=true;setData(null);setWorkshop(null);setError('');setNotice('');setForm(null);setDelivery(null);setConfirm(null);if(author)void load().catch(e=>{if(active)setError(e.message)});return()=>{active=false;loadSequence.current++}},[author,account]);
 async function run(fn,message=''){if(busy)return;setBusy(true);setError('');setNotice('');try{await fn();setNotice(message)}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function save(input){const result=await client.journal.request('courses',{...input,expectedVersion:data.version});setData(d=>({...d,state:result.state,version:result.version}));await load();}
 function edit(type,current){setForm({type,id:crypto.randomUUID(),title:current?.title||'',goal:current?.goal||''});setConfirm(null)}
 async function attach({type,value}){if(type==='chapter'&&workshop?.objectiveId){await save({type:'link-objective-chapter',courseId:course.id,topicId:topic.id,objectiveId:workshop.objectiveId,id:value.id,hash:value.draftHash});return;}await save({type:'link-'+type,courseId:course.id,topicId:topic.id,id:value.id,...(type==='resource'?{checksum:value.checksum}:{hash:value.draftHash})})}
 if(!client.journal.user)return <section className="cw-empty"><h1>Keep a course notebook.</h1><p>Sign in to organise your resources, chapters and topics across devices. Included activities remain available to try.</p><a className="button primary" href="/account.html">Sign in</a><button onClick={onBrowse}>Explore activities</button></section>;
 if(!author)return <>{error&&<p className="message error" role="alert">{error}</p>}<AssignmentShelf page client={client} busy={busy} onStart={item=>run(()=>onStart(item))}/></>;
 const sources=(topic?.resources||[]).map(binding=>({binding,resource:data?.resources.find(r=>r.id===binding.id)}));
 const chapters=(topic?.chapters||[]).map(binding=>({binding,chapter:data?.chapters.find(c=>c.id===binding.id)}));
 const readySources=sources.filter(s=>s.resource?.status==='reviewed'&&s.resource.checksum===s.binding.checksum);
 const readyChapters=chapters.filter(c=>c.chapter?.status==='published'&&c.chapter.hash===c.binding.hash);
 const selectTopic=id=>{setTopicId(id);setWorkshop(null);setDelivery(null);setForm(null);setConfirm(null)};
 return <div className="course-workspace"><div className="page-heading"><div><h1>From source to understanding.</h1><p>Keep your learning material, topics and reviewed chapters together.</p></div><button onClick={()=>edit('create-course')} disabled={busy}>New course</button></div>
 <LearnerCourses client={client} onStart={onStart}/>{client.access?.manages&&<OrganiserOverview client={client}/>}<div className="cw-status" aria-live="polite">{error&&<div className="message error" role="alert"><p>{error}</p><button disabled={busy} onClick={()=>run(load,'Loaded the saved notebook. Form edits are kept.')}>Reload notebook</button></div>}{notice&&<p className="message success">{notice}</p>}</div>
 {!data?<p>Opening your notebook…</p>:<div className="cw-layout"><aside className="cw-index"><h2>My courses</h2>{data.state.courses.map(c=><div className="cw-index-course" key={c.id}><button aria-current={course?.id===c.id?'page':undefined} onClick={()=>{setCourseId(c.id);selectTopic('')}}>{c.title}<span>{c.topics.length} {c.topics.length===1?'topic':'topics'}</span></button>{course?.id===c.id&&<nav aria-label="Course topics">{c.topics.map(t=><button key={t.id} aria-current={topic?.id===t.id?'page':undefined} onClick={()=>selectTopic(t.id)}>{t.title}</button>)}<button className="cw-add-topic" onClick={()=>edit('create-topic')}>Add a topic</button></nav>}</div>)}{!data.state.courses.length&&<p>Your first course will appear here.</p>}<a href="/welcome.html">People and access</a></aside><div className="cw-page">
 {form&&<form className="cw-form" onSubmit={e=>{e.preventDefault();void run(async()=>{await save({...form,courseId:course?.id,topicId:topic?.id});if(form.type==='create-course'){setCourseId(form.id);setTopicId('')}if(form.type==='create-topic')setTopicId(form.id);setForm(null)},'Notebook saved.')}}><h2>{form.type.includes('course')?'Course details':'Topic details'}</h2><label>Title<input required maxLength={120} value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label>What should the learner be able to explain or do?<textarea maxLength={1200} rows={3} value={form.goal} onChange={e=>setForm({...form,goal:e.target.value})}/></label><button className="primary" disabled={busy}>Save {form.type.includes('course')?'course':'topic'}</button><button type="button" onClick={()=>setForm(null)}>Cancel</button></form>}
 {!course&&!form&&<section className="cw-empty"><h2>A place for the whole subject.</h2><p>Create a course, divide it into topics and bring in your learning material. Every chapter keeps its reviewed sources with it.</p><button className="primary" onClick={()=>edit('create-course')}>Create my first course</button></section>}
 {course&&!workshop&&<><header className="cw-course-heading"><div><p>{course.title}</p><h2>{topic?.title||'Add the first topic'}</h2><p>{topic?.goal||course.goal||'Give this topic a clear learning goal.'}</p></div><details><summary>Notebook options</summary><button onClick={()=>edit('rename-course',course)}>Edit course</button>{topic&&<button onClick={()=>edit('rename-topic',topic)}>Edit topic</button>}<button onClick={()=>setConfirm({type:topic?'remove-topic':'remove-course',label:topic?.title||course.title})}>Remove {topic?'topic':'course'} from notebook</button>{topic&&<button onClick={()=>setConfirm({type:'remove-course',label:course.title})}>Remove whole course from notebook</button>}</details></header>
 {confirm&&<div className="cw-confirm"><h3>Remove “{confirm.label}”?</h3><p>This removes notebook links only. Sources, published chapters, assignments and learner progress remain available.</p><button disabled={busy} onClick={()=>run(async()=>{await save({...confirm,courseId:course.id,topicId:topic?.id});setConfirm(null)},'Removed from the notebook.')}>Remove notebook links</button><button onClick={()=>setConfirm(null)}>Keep it</button></div>}
 <CoursePlanner key={account+course.id} course={course} data={data} client={client} onSave={save} onStart={onStart} onReload={load} onPrepare={(step,job)=>{setTopicId(step.topicId);setWorkshop({kind:'plan',objectiveId:step.id,goal:step.objective,template:step.template,evidence:job.context.evidence.filter(e=>step.sourceRefs.includes(e.id))});}}/>
 {!topic?<button className="primary" onClick={()=>edit('create-topic')}>Add a topic</button>:<>
 <ol className="cw-route" aria-label="Topic preparation"><li className={readySources.length?'is-ready':''}><b>Collect and review</b><span>{readySources.length} reviewed sources</span></li><li className={readyChapters.length?'is-ready':''}><b>Prepare a chapter</b><span>{readyChapters.length} published chapters</span></li><li><b>Learn or assign</b><span>Keep each learner’s progress private</span></li></ol>
 <section className="cw-sources"><div className="section-heading"><h3>Sources for this topic</h3><button disabled={busy} onClick={()=>setWorkshop({kind:'add'})}>Add learning material</button></div>
 {sources.map(({binding,resource})=><article className="cw-source-row" key={binding.id}><div><b>{resource?.title||'Source unavailable'}</b><p>{!resource?'Removed or outside this library.':resource.checksum!==binding.checksum?'Source version changed. Review and link the current version.':resource.status==='reviewed'?`${resource.unitCount} passages · Reviewed`:'Needs source review'}</p></div>{resource&&<button onClick={()=>setWorkshop({kind:'source',id:resource.id})}>Read and review</button>}<button className="text-button" disabled={busy} onClick={()=>run(()=>save({type:'unlink-resource',courseId:course.id,topicId:topic.id,id:binding.id}))}>Remove link</button></article>)}
 {!sources.length&&<p>Add notes or a document, or reuse something already in your library.</p>}
 <details><summary>Use a source already in my library</summary><LibraryPicker key={client.journal.user.id+topic.id} linked={topic.resources.map(r=>r.id)} disabled={busy} onPick={r=>run(()=>attach({type:'resource',value:r}),'Source linked to this topic.')}/></details>
 </section>
 <EvidenceFinder key={account+topic.id} sources={readySources.map(s=>s.resource)} goal={topic.goal||course.goal} disabled={busy} onPrepare={setWorkshop} onLink={r=>run(()=>attach({type:'resource',value:r}),'Source linked to this topic.')}/>
 <section className="cw-chapters"><div className="section-heading"><h3>Chapters and activities</h3><button className="primary" disabled={busy||!readySources.length} onClick={()=>setWorkshop({kind:'plan'})}>Prepare a chapter</button></div>{!readySources.length&&<p>Review a source before asking the AI to create a chapter.</p>}{readySources.length>0&&<p className="cw-note">Chapters made here are for this topic. To link a chapter to a course objective (needed before assigning a course), use <b>Prepare this activity</b> on that objective in the course route.</p>}{chapters.map(({binding,chapter})=>{const valid=chapter?.hash===binding.hash,published=valid&&chapter.status==='published',item=client.items.find(i=>i.jobId===binding.id);return <article key={binding.id}><div><span>{chapter?formatName(chapter.template)+' · '+chapterCopyLabel(chapter):'Chapter unavailable'}</span><h3>{chapter?.title||'This chapter is no longer available'}</h3><p>{!chapter?'The original chapter may have been removed.':!valid?'This chapter changed. Review and link its current version.':published?'Reviewed and ready to learn.':'Teaching review required before use.'}</p></div><div className="cw-actions">{chapter&&<button onClick={()=>setWorkshop({kind:'job',id:chapter.id})}>Open review</button>}{published&&<button className="primary" disabled={busy} onClick={()=>run(async()=>{await client.refresh();const exact=client.items.find(i=>i.jobId===binding.id);if(!exact)throw Error('This reviewed chapter is no longer available.');await onStart(exact,true,topic.goal||course.goal||undefined)})}>Use for my learning</button>}{published&&client.access?.manages&&<button onClick={()=>setDelivery(chapter)}>Assign to learners</button>}<button className="text-button" disabled={busy} onClick={()=>run(()=>save({type:'unlink-chapter',courseId:course.id,topicId:topic.id,id:binding.id}))}>Remove link</button></div></article>})}{!chapters.length&&<p>Prepare a new chapter or open an existing draft, then add it to this topic. Publication still requires a teaching review.</p>}<button className="text-button" onClick={()=>setWorkshop({kind:'library'})}>Open existing chapters</button></section>
 {delivery&&<DeliveryPanel chapter={delivery} client={client} onClose={()=>setDelivery(null)}/>}
 </>}
 </>}
 {course&&topic&&workshop&&<ChapterWorkshop key={JSON.stringify(workshop)} request={workshop} topic={{...topic,goal:topic.goal||course.goal,resourceMetadata:sources.map(s=>s.resource).filter(Boolean)}} client={client} onAttach={attach} onClose={()=>{setWorkshop(null);void run(async()=>{await load();await client.refresh()})}}/>}
 </div></div>}</div>;
}

function DeliveryPanel({chapter,client,onClose}){
 const [selected,setSelected]=useState([]),[busy,setBusy]=useState(false),[result,setResult]=useState([]),[preview,setPreview]=useState(false);
 const learners=(client.access?.roster||[]).filter(m=>m.role==='learner'&&m.status==='active'&&m.manager===client.access.accountReference);
 const item=client.items.find(i=>i.jobId===chapter.id);
 return <section className="cw-delivery"><h3>Assign “{chapter.title}”</h3><p>Learners receive this published version. Your source library and their private responses are not shared with the group.</p><button onClick={()=>setPreview(!preview)}>{preview?'Close introduction':'Preview learner introduction'}</button>{preview&&item&&<div className="cw-preview"><h4>{item.pack.title}</h4><p>{contentOf(item.pack).hook}</p><ul>{activitiesOf(item.pack).map(a=><li key={a.key}>{a.objective||a.label}</li>)}</ul><p>The learner can start directly. No author review screen or answer key is shown in this introduction.</p></div>}<fieldset><legend>Choose learners</legend>{learners.map(m=><label className="check" key={m.accountReference}><input type="checkbox" disabled={busy} checked={selected.includes(m.accountReference)} onChange={e=>setSelected(e.target.checked?[...selected,m.accountReference]:selected.filter(x=>x!==m.accountReference))}/>{m.label||m.accountReference.slice(0,12)}{m.group?' — '+m.group:''}</label>)}{!learners.length&&<p>No active learners in your group yet. <a href="/welcome.html">Invite a learner</a> before assigning.</p>}</fieldset><button className="primary" disabled={busy||!selected.length} onClick={async()=>{setBusy(true);const results=[];for(const learner of selected){try{await pilotRequest({action:'assign',accountReference:learner,jobId:chapter.id,draftHash:chapter.hash});results.push({learner,ok:true})}catch(e){results.push({learner,ok:false,error:e.message})}}setResult(results);setBusy(false)}}>{busy?'Assigning…':'Assign reviewed chapter'}</button><button disabled={busy} onClick={onClose}>Close assignment</button><div aria-live="polite">{result.map(r=><p key={r.learner}>{learners.find(l=>l.accountReference===r.learner)?.label||r.learner.slice(0,12)}: {r.ok?'Assigned. It is ready in their Studio.':r.error}</p>)}</div></section>;
}
