import {originalBytes} from '../knowledge-client.js';
import React,{useEffect,useRef,useState} from 'react';
import {zipSync,strToU8} from 'fflate';
import './data-controls.css';
import {workspaceExportFiles} from './workspace-export.js';
import {allowanceSummary,ALLOWANCE_HREF} from './allowance-summary.js';
const periods=[[0,'Until I delete it'],[7,'7 days'],[30,'30 days'],[90,'90 days'],[365,'1 year']];
const save=(name,bytes,type)=>{const u=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)};
const size=n=>n<1024?`${n} B`:`${(n/1048576).toFixed(1)} MB`;
export function DataControls({client,onChanged}){
 const [data,setData]=useState(null),[policy,setPolicy]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[preview,setPreview]=useState(null),[confirmed,setConfirmed]=useState(false),[classCount,setClassCount]=useState(null);
 const admin=client.access?.admin===true;
 const dialog=useRef(null);useEffect(()=>{if(preview&&dialog.current&&!dialog.current.open)dialog.current.showModal()},[preview]);
 const call=body=>client.journal.request('data',body?{epoch:data?.epoch,...body}:undefined);
 async function reload(){const d=await call();client.journal.dataEpoch=d.epoch;client.journal.applyDataReset(d.resetMs,d.resetKind);setData(d);setPolicy(d.policy);}
 async function run(fn){if(busy)return;setBusy(true);setError('');setNotice('');try{await fn()}catch(e){setError(e.message)}finally{setBusy(false)}}
 useEffect(()=>{if(client.journal.user)void run(reload)},[]);
 async function plan(mode,id){const d=await call({action:'preview',mode,id});setClassCount(null);if(mode==='learner'&&d.preview.counts.classRows>0)client.journal.request('classes').then(c=>setClassCount((c.joined||[]).length)).catch(()=>setClassCount(-1));setPreview(d.preview);setConfirmed(false);}
 async function remove(){const d=await call({action:'delete',mode:preview.mode,id:preview.id,hash:preview.hash,confirmed:true});setPreview(null);setConfirmed(false);await reload();await client.refresh();onChanged?.();setNotice(d.operation.status==='complete'?'Deletion completed and checked.':'Deleted from Mosaic. One clean-up step with an outside service still needs attention below.');}
 async function mediaBytes(id){const r=await fetch('/api/learning/data',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Mosaic-Learner':client.journal.user.id},body:JSON.stringify({action:'download',epoch:data.epoch,id})});if(!r.ok){const d=await r.json();throw Error(d.error||'Recording could not be downloaded.')}return new Uint8Array(await r.arrayBuffer());}
 async function exportData(scope){
  if(scope==='workspace'){const files=await workspaceExportFiles(call,(n,total)=>setNotice(`Preparing source ${n} of ${total} for your archive…`),originalBytes);save('mosaic-workspace-export.zip',zipSync(files,{level:0}),'application/zip');setNotice('Extracted materials, chapters and plans downloaded. Check originals-index.json for included files; originals above 100 MB remain available individually. No AI requests used.');return;}
  const {export:record}=await call({action:'export',scope}),files={'mosaic-data.json':strToU8(JSON.stringify(record,null,2))},media=record.media?.filter(m=>m.status==='ready')||[];
  if(media.reduce((n,m)=>n+m.bytes,0)>100*1048576){save('mosaic-'+scope+'-data.json',JSON.stringify(record,null,2),'application/json');setNotice('Your data and media index were downloaded. Saved media exceeds 100 MB; download individual recordings below.');return;}
  for(let i=0;i<media.length;i++){setNotice(`Adding saved recording ${i+1} of ${media.length} to your archive…`);files['media/'+media[i].id+(media[i].segment===-1?'.mp4':media[i].segment<=-10?'.webp':'.mp3')]=await mediaBytes(media[i].id);}
  files['README.txt']=strToU8('Mosaic export\nThe JSON contains your saved data and exact source references. media/ contains saved MP3 audio and MP4 video; match their filenames to media[].id. No audio was regenerated. Workspace archives include retained source originals up to the archive limit; check originals-index.json. Passwords and provider/infrastructure backups are not included.');
  save('mosaic-'+scope+'-export.zip',zipSync(files,{level:0}),'application/zip');setNotice(`Export downloaded${media.length?` with ${media.length} saved recordings`:''}. No AI requests used.`);
 }
 if(!client.journal.user)return <section className="surface"><h1>Your data</h1><p>Sign in to manage your saved account data.</p><a href="/account.html">Sign in</a></section>;
 return <div className="data-controls"><div className="page-heading"><div><h1>Your work. Your choice.</h1><p>Keep what helps, take a copy, and clear what you no longer need.</p></div><button disabled={busy} onClick={()=>run(reload)}>Refresh and check retention</button></div>
 <div aria-live="polite">{busy&&<p className="message">Working on your saved data…</p>}{notice&&<p className="message success">{notice}</p>}{error&&<p className="message error" role="alert">{error}</p>}</div>
 {data&&<><section className="data-summary" aria-label="Your data at a glance"><div><h2>What Mosaic keeps</h2><p>Your profile and goals, your progress, the material you add, the chapters, plans, conversations and episodes made from it, and any recordings you save.</p></div><div><h2>What you can download</h2><p>A copy of your learning and recordings, and a copy of your materials and chapters, each as a zip file.</p></div><div><h2>What you can delete</h2><p>Any single recording, episode or source, or all your learning data at once. Your sign-in account stays until you close it on the <a href="/welcome.html">Welcome page</a>.</p></div></section>
 <div className="data-layout"><div>
 <section className="surface data-section"><h2>Your recordings stay with you.</h2><p>Play a saved recording on a later visit without generating it again. New script wording or voice settings create a different recording.</p><p className="data-total">{data.media.filter(m=>m.status==='ready').length} saved recordings <span>{size(data.media.reduce((n,m)=>n+m.bytes,0))}</span></p>
 {!data.storageConnected&&<p role="alert">Private media storage is unavailable. No new narration will be requested.</p>}
 {data.media.length?<div className="data-recordings">{data.media.map(m=><article key={m.id}><div><h3>{data.jobs.find(j=>j.id===m.script_id)?.title||'Saved episode'}</h3><p>{m.segment===-1?'Full video':m.segment===-2?'Full podcast':m.segment<=-10?'Story backdrop':'Passage '+(m.segment+1)} · {m.status==='ready'?size(m.bytes):m.status} · {new Date(m.created).toLocaleDateString()}</p></div><div className="data-actions"><button disabled={busy||m.status!=='ready'} onClick={()=>run(async()=>{save('mosaic-'+m.id+(m.segment===-1?'.mp4':'.mp3'),await mediaBytes(m.id),m.segment===-1?'video/mp4':'audio/mpeg');setNotice('Saved recording downloaded. No AI request used.');})}>Download media</button><button disabled={busy} onClick={()=>run(()=>plan('media',m.id))}>Delete media</button></div></article>)}</div>:<p>No recordings saved yet. Play a reviewed podcast or cartoon to save its narration.</p>}
 </section>
 {data.costs&&(()=>{const summary=allowanceSummary(data.costs.budget);return <section className="surface data-section"><h2>Your AI use</h2>{summary&&<p className="data-total">{summary.text}</p>}<p>You made {data.costs.rows.length} AI request{data.costs.rows.length===1?'':'s'} in the last 30 days. Saved games, recordings and your own edits don’t use AI.</p><p><a className="allowance-link" href={ALLOWANCE_HREF}>Need more? Ask for a higher allowance</a></p>{admin&&<><p className="data-total">${data.costs.workspace.estimateUsd.toFixed(4)} <span>estimated workspace AI cost · last 30 days · administrator view</span></p><p>{data.costs.workspace.requests} tracked requests. {data.costs.workspace.unpriced} without confirmed pricing or usage. Older requests before tracking began are not included.</p><p>{data.costs.notice}</p></>}<details><summary>Details</summary>{data.costs.rows.length?data.costs.rows.map(r=><article className="data-row" key={r.id}><div><strong>{r.model}</strong><p>{new Date(r.created).toLocaleString()} · {r.usage?.seconds!==undefined?`${r.usage.seconds} seconds transcribed`:r.usage?.inputTokens!==undefined?`${r.usage.inputTokens} input / ${r.usage.outputTokens} output tokens · ${r.usage.cachedTokens??'unknown'} cached`:r.usage?.inputBytes!==undefined?`${r.usage.inputBytes} UTF-8 input bytes`:'Usage not confirmed'}</p>{r.usage?.cachedTokens===null&&<p>Cache breakdown missing; estimate uses the full input rate.</p>}</div>{admin&&<span>{r.estimate_micros===null?'Unknown':'$'+(r.estimate_micros/1e6).toFixed(4)}</span>}</article>):<p>No tracked requests for this learner yet.</p>}{admin&&<p className="subtle">Rates are saved with each request. <a href="https://dev.meta.ai/docs/pricing-rate-limits" target="_blank" rel="noreferrer">Meta list prices</a> · <a href="https://docs.fish.audio/developer-guide/models-pricing/pricing-and-rate-limits" target="_blank" rel="noreferrer">Fish list prices</a>. Account discounts and credits may differ.</p>}</details></section>})()}<section className="surface data-section"><h2>Personal learning records</h2><p>Your preferences, programmes and progress use your learner account. Course plans, tutor conversations, episodes and recordings are kept privately alongside this workspace.</p><div className="form-actions"><button disabled={busy} onClick={()=>run(()=>exportData('learner'))}>Export my learning and media</button><button disabled={busy} onClick={()=>run(()=>plan('learner'))}>Delete my learning data</button></div>
 <h3 className="data-subheading">Conversations, episodes, course plans and imports</h3>{data.jobs.length?data.jobs.map(j=><article className="data-row" key={j.id}><div><strong>{j.title}</strong><p>{j.kind} · {new Date(j.created).toLocaleDateString()}</p></div><button disabled={busy} onClick={()=>run(()=>plan('episode',j.id))}>{j.kind==='course-plan'?'Delete course plan':['search','transcript'].includes(j.kind)?'Delete saved import':'Delete episode'}</button></article>):<p>No saved conversations, episodes, course plans or imports.</p>}
 </section>
 <section className="surface data-section"><h2>Workspace materials</h2><p>These belong to the private workspace. Deleting a source also removes your derived chapters, course plans and episodes. If another learner has an episode from it, deletion waits for them to remove that copy. Learner progress and downloaded copies are separate.</p><button disabled={busy} onClick={()=>run(()=>exportData('workspace'))}>Export materials and chapters</button>{data.resources.map(r=><article className="data-row" key={r.id}><div><strong>{r.title}</strong><p>{new Date(r.created).toLocaleDateString()}</p></div><button disabled={busy} onClick={()=>run(()=>plan('resource',r.id))}>Delete source</button></article>)}
 </section></div><aside>
 <section className="data-policy"><h2>How long to keep it</h2><p>Age is measured from recording or source creation, and from the last saved change for conversations and learning records. Listening does not extend it.</p>{[['learner','mediaDays','Audio recordings'],['learner','creativeDays','Conversations, episodes, course plans and imports'],['learner','progressDays','Preferences and learning progress'],['workspace','resourceDays','Sources and derived learning material']].map(([scope,key,label])=><label key={key}>{label}<select value={policy?.[scope]?.[key]||0} disabled={busy} onChange={e=>setPolicy({...policy,[scope]:{...policy[scope],[key]:Number(e.target.value)}})}>{periods.map(([value,label])=><option value={value} key={value}>{label}</option>)}</select></label>)}
 <button className="primary" disabled={busy} onClick={()=>run(async()=>{for(const scope of ['learner','workspace']){await call({action:'retention',scope,policy:policy[scope],epoch:(await call()).epoch});}await reload();setNotice('Retention saved. Background passes use these choices; this refresh also checks now.');})}>Save retention choices</button>
 <p className="subtle">{data.maintenance?.enabled?'Background cleanup is enabled. The scheduled service checks saved policies while you are away; normal reads also check at most hourly.':'Background cleanup is not enabled yet. Normal reads check at most hourly, and this screen checks immediately.'} {data.maintenance?.lastRun?'Latest cleanup service pass: '+new Date(data.maintenance.lastRun.at).toLocaleString()+' · '+data.maintenance.lastRun.status+'.':'No background pass recorded yet.'}</p></section>
 <section className="data-note"><h3>What deletion covers</h3><p>Deleting removes the data from Mosaic and checks that it’s gone. Mosaic also asks the outside services it used to delete what they stored. If one of those requests fails, it shows on this page so you can try again.</p><p>It doesn’t delete your sign-in account or copies you downloaded.</p><details><summary>Details</summary><p>Mosaic checks removal from its active storage and asks the AI text service to delete the responses it stored. Failed requests stay listed under “Cleanup to finish” for retry.</p><p>Deletion does not cover your sign-in account, downloaded copies, another device’s offline files, or service and infrastructure backups. Voice presets at the speech service remain available; no promise of zero retention by those services is made.</p><p>Encrypted recovery copies are scheduled for deletion after seven days. They are restricted to recovery work; restoring a copy requires reapplying later deletion requests before access is reopened.</p><p>Content-free AI allowance receipts remain for up to 24 hours. Usage receipts and action history are kept for 30 days, then removed by maintenance. Deleting learning data removes its link to usage receipts. Service bills and backups are separate.</p></details></section>
 </aside></div>
 {data.operations.some(o=>!['complete','cancelled'].includes(o.status))&&<section className="surface data-section"><h2>Cleanup to finish</h2>{data.operations.filter(o=>!['complete','cancelled'].includes(o.status)).map(o=><div className="data-row" key={o.id}><p>{o.localDone?'Removed from Mosaic. Asking an outside service to delete its copy is still pending.':'Cleanup is pending. Saves are paused until it finishes.'}</p><button disabled={busy} onClick={()=>run(async()=>{await call({action:'resume',id:o.id});await reload();await client.refresh();onChanged?.();setNotice('Cleanup checked.');})}>Resume cleanup</button></div>)}</section>}
 <details className="data-history"><summary>Recent data actions</summary>{data.events.map((e,i)=><p key={i}>{new Date(e.created).toLocaleString()} — {e.action.replaceAll('-',' ')}</p>)}</details>
 </>}
 {preview&&<dialog ref={dialog} className="data-confirm" aria-labelledby="deletion-title" onCancel={e=>{e.preventDefault();if(!busy)setPreview(null)}}><section><h2 id="deletion-title">Review this deletion</h2><p>This permanently removes the selected saved data. Export anything you want to keep first.</p><dl>{Object.entries(preview.counts).map(([key,n])=><div key={key}><dt>{{classRows:'Class memberships, leaderboard entries and shared explanations',recordings:'Audio recordings',creative:'Conversations, episodes, course plans and imports',chapters:'Generated chapters',resources:'Uploaded sources',learnerRows:'Learning record versions',providerResponses:'AI responses stored by the AI service',courseAssignments:'Course assignments',sharingSettings:'Course sharing settings',collections:'Collection sources or access',assignedQuestionSets:'Assigned question sets (games kept)'}[key]}</dt><dd>{n}</dd></div>)}</dl>{preview.mode==='learner'&&preview.counts.classRows>0&&<p className="data-warning" role="alert"><b>{classCount>0?`You’ll also leave your ${classCount} class${classCount===1?'':'es'}.`:'You’ll also leave your classes.'}</b> Your class memberships, leaderboard entries and shared explanations are removed. To join again you’ll need each class code.</p>}{preview.counts.assignedQuestionSets>0&&<p>Question-set removal keeps the assigned games and each learner’s private attempts. Sharing is switched off for the changed course version.</p>}<p>Your sign-in account stays available. Offline and downloaded copies are outside this deletion.</p><label className="check"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I understand which records will be permanently removed.</label><div className="form-actions"><button disabled={busy} onClick={()=>setPreview(null)}>Keep my data</button><button className="data-danger" disabled={busy||!confirmed} onClick={()=>run(remove)}>Delete permanently</button></div></section></dialog>}
 </div>;
}
