import React,{useEffect,useRef,useState} from 'react';
import {draftHash} from '../game-modes/draft-engine.js';
import {activitiesOf} from './programme.js';
import {emptyExplore,exploreAction,exploreView,EXPLORE_LABELS} from './explore-model.js';
import {ExplorePlayer,LessonSources} from './ExplorePlayer.jsx';
import {AllowanceUsed} from './AllowanceLine.jsx';

export function ExploreReview({job,busy,onSave,onApprove}){
 const [draft,setDraft]=useState(job.draft),[checked,setChecked]=useState(false),[preview,setPreview]=useState(false),[previewState,setPreviewState]=useState(emptyExplore(job.draft,job.draftHash));
 useEffect(()=>{setDraft(job.draft);setChecked(false);setPreviewState(emptyExplore(job.draft,job.draftHash))},[job.draftHash]);
 const change=(path,value)=>{const next=structuredClone(draft);let at=next;for(const k of path.slice(0,-1))at=at[k];at[path.at(-1)]=path.at(-1)==='accepted'?value.split('\n'):value;setDraft(next);setChecked(false)};
 const field=(label,path,value,max=1400)=><label key={path.join('.')}>{label}<textarea rows={value.length>180?4:2} value={value} maxLength={max} onChange={e=>change(path,e.target.value)}/></label>;
 return <section className="explore-review"><h2>Review the lesson before using it.</h2><p>Check the model, source support, simplifications, task answers and rubric. Free edits invalidate approval. Previewing is local and does not save learner responses.</p>{field('Lesson title',['title'],draft.title,120)}{field('Objective',['objective'],draft.objective,400)}{field('Introduction',['introduction'],draft.introduction,900)}
 {draft.investigations.map((b,i)=><details key={b.id}><summary>{EXPLORE_LABELS[b.type]}: {b.title}</summary>{['title','question','explanation','limitation'].map(k=>field(k[0].toUpperCase()+k.slice(1),['investigations',i,k],b[k],k==='title'?120:k==='question'?600:k==='limitation'?500:1200))}{b.items.map((v,n)=><div className="explore-review-item" key={n}>{field('Item '+(n+1),['investigations',i,'items',n,'label'],v.label,100)}{field('Explanation',['investigations',i,'items',n,'detail'],v.detail,700)}<label>Value / position<input type="number" value={v.value} onChange={e=>change(['investigations',i,'items',n,'value'],Number(e.target.value))}/></label>{b.type==='evidence-sort'&&<label>Reviewed category<select value={v.category} onChange={e=>change(['investigations',i,'items',n,'category'],Number(e.target.value))}>{b.categories.map((c,k)=><option key={k} value={k}>{c}</option>)}</select></label>}</div>)}{b.controls.map((c,n)=><fieldset key={n}><legend>{c.label} ({c.unit})</legend>{['label','unit'].map(k=>field(k,['investigations',i,'controls',n,k],c[k],k==='unit'?30:80))}{['min','max','step','initial'].map(k=><label key={k}>{k}<input type="number" step="any" value={c[k]} onChange={e=>change(['investigations',i,'controls',n,k],Number(e.target.value))}/></label>)}</fieldset>)}{b.links.length>0&&<ul>{b.links.map((l,n)=><li key={n}>{b.items[l.from].label} — {l.label} — {b.items[l.to].label}</li>)}</ul>}<LessonSources sources={draft.sources} refs={b.sourceRefs}/></details>)}
 {draft.assessment.map((q,i)=><details key={q.id}><summary>Task {i+1}: {q.type.replaceAll('-',' ')}</summary>{['prompt','hint','explanation'].map(k=>field(k,['assessment',i,k],q[k],k==='prompt'?1000:k==='hint'?500:1400))}{q.type==='short-answer'&&field('Accepted alternatives, one per line',['assessment',i,'accepted'],q.accepted.join('\n'),960)}{['numeric','worked-solution'].includes(q.type)&&<>{['answer','tolerance'].map(k=><label key={k}>{k}<input type="number" step="any" value={q[k]} onChange={e=>change(['assessment',i,k],Number(e.target.value))}/></label>)}{field('Unit',['assessment',i,'unit'],q.unit,30)}</>}{q.steps.map((s,n)=>field('Reviewed step '+(n+1),['assessment',i,'steps',n],s,500))}{q.criteria.map((c,n)=><fieldset key={n}><legend>Criterion {n+1}</legend>{['label','evidence','improve'].map(k=>field(k,['assessment',i,'criteria',n,k],c[k],k==='label'?120:600))}</fieldset>)}<LessonSources sources={draft.sources} refs={q.sourceRefs}/></details>)}
 <div className="form-actions"><button disabled={busy||JSON.stringify(draft)===JSON.stringify(job.draft)} onClick={()=>onSave({...draft,assessment:draft.assessment.map(q=>({...q,accepted:typeof q.accepted==='string'?q.accepted.split('\n').map(v=>v.trim()).filter(Boolean):q.accepted}))})}>Save lesson edits</button><button disabled={JSON.stringify(draft)!==JSON.stringify(job.draft)} onClick={()=>setPreview(!preview)}>{preview?'Close preview':'Preview this exact lesson'}</button></div>{preview&&<ExplorePlayer key={job.draftHash} view={{...exploreView(job.draft,previewState),reviewerSawAnswers:true}} onAction={a=>setPreviewState(exploreAction(job.draft,previewState,a,Date.now()))}/>}
 <label className="check"><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/>I checked every model, claim, answer, unit, analogy and criterion against the source and intended learner context.</label><button className="primary" disabled={busy||!checked||JSON.stringify(draft)!==JSON.stringify(job.draft)} onClick={onApprove}>Approve this lesson</button></section>;
}
export function ExploreStudio({item,unit,client,onBack,initialJobId=null}){
 const {pack}=item,identity={packId:pack.id,contentHash:draftHash(pack)};
 const [jobs,setJobs]=useState([]),[id,setId]=useState(initialJobId),[focus,setFocus]=useState(unit.activityKeys[0]),[budget,setBudget]=useState(null),[view,setView]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');
 const alive=useRef(true),lock=useRef(false),requestKey=useRef(null),job=jobs.find(j=>j.id===id);
 const request=body=>client.journal.request((item.readOnly&&!body?'loop/banks':'creative')+(body?'':'?'+new URLSearchParams({...identity,...(id?{selectedJob:id}:{})})),body?{...identity,...body}:undefined);
 const adopt=data=>{if(alive.current){setJobs(data.jobs.filter(j=>j.kind==='explore'));setBudget(data.budget)}};
 const run=async fn=>{if(lock.current)return;lock.current=true;setBusy(true);setError('');setNotice('');try{await fn()}catch(e){if(alive.current)setError(e.message)}finally{lock.current=false;if(alive.current)setBusy(false)}};
 const loadView=async(j=job)=>{const v=await client.journal.request('explore?'+new URLSearchParams({lessonId:j.id,lessonHash:j.draftHash}));if(alive.current)setView(v)};
 useEffect(()=>{alive.current=true;if(client.journal.user)void run(async()=>adopt(await request()));return()=>{alive.current=false}},[pack.id]);
 useEffect(()=>{setView(null);let stale=false;if(job?.status==='published')void client.journal.request('explore?'+new URLSearchParams({lessonId:job.id,lessonHash:job.draftHash})).then(v=>{if(!stale&&alive.current)setView(v)}).catch(e=>{if(!stale)setError(e.message)});return()=>{stale=true}},[id,job?.draftHash,job?.status]);
 useEffect(()=>{const pending=jobs.find(j=>['running','starting'].includes(j.status));if(!pending||error)return;const timer=setTimeout(()=>void run(async()=>adopt(await request({action:'check',id:pending.id}))),3500);return()=>clearTimeout(timer)},[jobs,busy,error]);
 const generate=async()=>{const d=await request({action:'create',kind:'explore',activityKey:focus,requestKey:requestKey.current||(requestKey.current=crypto.randomUUID())});adopt(d);setId(d.jobId);requestKey.current=null;adopt(await request({action:'run',id:d.jobId}))};
 const action=async a=>run(async()=>{const v=await client.journal.request('explore',{lessonId:job.id,lessonHash:job.draftHash,expectedVersion:view.version,action:a});if(alive.current){setView(v);setNotice('Saved to your learner account.')}});
 if(!client.journal.user)return <section className="surface"><h2>Explore, explain and keep your progress.</h2><p>Sign in to prepare reviewed lessons and save your own investigations.</p><a className="button" href="/account.html">Sign in</a><button onClick={onBack}>Back to programme</button></section>;
 return <section className="explore-studio"><button className="text-button" onClick={onBack}>Back to my programme</button><header className="explore-heading"><h2>Find out what changes. Explain why.</h2><p>Investigate a model, test an idea, then show your reasoning in your own words.</p></header><div className="explore-layout"><div className="explore-primary">
 {!job&&(!item.readOnly?<section className="explore-brief"><h3>A lesson built around your question.</h3><label>Focus<select value={focus} disabled={busy} onChange={e=>{setFocus(e.target.value);requestKey.current=null}}>{activitiesOf(pack).filter(a=>unit.activityKeys.includes(a.key)).map(a=><option key={a.key} value={a.key}>{a.label}</option>)}</select></label><p>Starting point: <strong>{unit.profile.level}</strong>. {unit.profile.interests.length?'Examples can connect to '+unit.profile.interests.slice(0,2).join(' and ')+'.':''}</p><p>{unit.profile.struggles||'Make a prediction, try the model and compare the evidence.'}</p><p>The AI chooses suitable experiments, graphs, timelines, connection maps, conceptual diagrams, worked examples or evidence sorting. The lesson then offers short answers, numerical reasoning, worked solutions or rubric-guided writing.</p><p className="subtle">Your reviewed source, goal, study context, level, interests, focus and access preferences are sent to Meta’s AI service. Review the complete lesson before use. One generation request; edits and saved practice are free of AI allowance.</p><button className="primary" disabled={busy||!budget?.remaining} onClick={()=>run(generate)}>Create an Explore lesson</button><AllowanceUsed budget={budget}/></section>:<section className="explore-brief"><h3>Your reviewed Explore lessons</h3><p>{jobs.length?'Choose an assigned lesson from your saved work.':'Your organiser has not attached an Explore lesson to this programme yet. Your game and other learning activities are still available.'}</p></section>)}
 {error&&<div role="alert" className="message error"><p>{error}</p><button disabled={busy} onClick={()=>run(async()=>{adopt(await request());if(job?.status==='published')await loadView()})}>Refresh saved lesson</button></div>}{notice&&<p role="status" className="explore-save-status">{notice}</p>}
 {job&&['queued','running','starting','failed','interrupted'].includes(job.status)&&<section className="explore-brief"><h3>{['running','starting'].includes(job.status)?'Preparing your investigation…':'Your saved request'}</h3><p>{job.error||'You can leave and return. Checking this request does not generate a replacement.'}</p><button disabled={busy} onClick={()=>run(async()=>adopt(await request({action:job.status==='queued'?'run':'check',id:job.id})))}>{job.status==='queued'?'Start saved request':'Check saved request'}</button></section>}
 {job?.status==='review'&&<ExploreReview job={job} busy={busy} onSave={draft=>run(async()=>adopt(await request({action:'edit',id:job.id,draftHash:job.draftHash,draft})))} onApprove={()=>run(async()=>adopt(await request({action:'review',id:job.id,draftHash:job.draftHash,confirmed:true})))}/>}
 {job?.status==='published'&&!view&&!error&&<p role="status">Opening your saved lesson…</p>}
 {job?.status==='published'&&view&&<><ExplorePlayer key={job.id+job.draftHash} view={view} busy={busy} onAction={action}/>{!item.readOnly&&<button className="text-button" disabled={busy} onClick={()=>run(async()=>adopt(await request({action:'reopen',id:job.id,draftHash:job.draftHash})))}>Revise the lesson</button>}</>}
 </div><aside className="explore-shelf"><h3>Saved lessons</h3>{!item.readOnly&&<><p>{budget?`${budget.remaining} AI requests available`:'Checking allowance…'}</p>{budget&&<a className="allowance-link" href="/welcome.html#allowance">Need more? Ask for a higher allowance</a>}<button disabled={busy} onClick={()=>{setId(null);setView(null);setNotice('')}}>Prepare another lesson</button></>}{jobs.map(j=><button key={j.id} aria-pressed={id===j.id} disabled={busy} onClick={()=>{setId(j.id);setError('');setNotice('')}}><strong>{j.draft?.title||'Lesson in progress'}</strong><span>{j.status}</span></button>)}<button disabled={busy} onClick={()=>run(async()=>{adopt(await request());if(job?.status==='published')await loadView()})}>Refresh saved work</button><p>Lessons are bound to reviewed sources. Predictions, first responses, clues and rubric self-checks stay distinct from grades and game scores.</p></aside></div></section>;
}
