import {SourceCollections} from './SourceCollections.jsx';
import {ChapterWorkshop} from './ChapterWorkshop.jsx';
import React,{useEffect,useRef,useState} from 'react';
import {DOCUMENT_ACCEPT,extractDocument} from '../document-extraction.js';
import {LibraryPicker} from './SourceLibrary.jsx';
import {EvidenceFinder} from './EvidenceFinder.jsx';
import {workshopRequest,canPrepare} from './client.js';
import {originalBytes,fileBase64,saveOriginal} from '../knowledge-client.js';
import './knowledge.css';
const RECORDINGS='.wav,.mp3,.aac,.m4a,.mp4,.flac,.ogg,.opus,.webm,.mkv,.mov';
export function KnowledgeLibrary({client}){
 const [mode,setMode]=useState('browse'),[source,setSource]=useState(null),[versions,setVersions]=useState([]),[settings,setSettings]=useState(null),[title,setTitle]=useState(''),[text,setText]=useState(''),[filename,setFilename]=useState(''),[language,setLanguage]=useState(''),[url,setURL]=useState(''),[warnings,setWarnings]=useState([]),[file,setFile]=useState(null),[retain,setRetain]=useState(false),[parent,setParent]=useState(null),[reviewed,setReviewed]=useState(false),[permitted,setPermitted]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[revision,setRevision]=useState(0),[job,setJob]=useState(null);
 const [selection,setSelection]=useState(null),[ocr,setOCR]=useState(false);
 const lock=useRef(false),requestKey=useRef(null),life=useRef(true);const author=canPrepare(client);
 const run=async fn=>{if(lock.current)return;lock.current=true;setBusy(true);setError('');setNotice('');try{await fn()}catch(e){if(life.current)setError(e.message)}finally{lock.current=false;if(life.current)setBusy(false)}};
 const refresh=async()=>{const d=await workshopRequest('knowledge');if(life.current)setSettings(d)};
 useEffect(()=>{life.current=true;if(author)void run(refresh);return()=>{life.current=false}},[]);
 const open=async id=>{const r=(await workshopRequest('resources/'+id)).resource,v=await workshopRequest('knowledge/versions/'+id);if(life.current){setSource(r);setVersions(v.versions);setReviewed(false);setMode('source')}};
 const reset=(next,previous=null)=>{setMode(next);setParent(previous);setTitle(previous?previous.title:'');setLanguage(previous?.provenance?.language||'');setText('');setFilename('');setURL('');setWarnings([]);setFile(null);setRetain(false);setPermitted(false);setError('');setNotice('');setJob(null);setOCR(false);requestKey.current=null;};
 const loadResult=d=>{setText(d.text);if(d.language)setLanguage(d.language);setTitle(d.title||d.filename?.replace(/\.[^.]+$/,'')||'Recording notes');setFilename(d.filename||'');setWarnings(d.warnings||[]);if(d.url)setURL(d.url);setMode('edit')};
 async function selectFile(f){if(f.size>8*1048576)throw Error('Choose a file up to 8 MB.');setJob(null);setURL('');setText('');setWarnings([]);setPermitted(false);setRetain(false);setFile(f);setFilename(f.name);setTitle(f.name.replace(/\.[^.]+$/,''));requestKey.current=null;const ext=f.name.split('.').at(-1).toLowerCase();if(RECORDINGS.split(',').includes('.'+ext)){setMode('recording');if(!/^[a-z]{2}$/.test(language))setLanguage('');setText('');setWarnings([])}else loadResult(await extractDocument(f,{ocr}));}
 async function transcribe(){const bytes=new Uint8Array(await file.arrayBuffer()),key=requestKey.current||(requestKey.current=crypto.randomUUID());const d=await workshopRequest('knowledge/jobs',{kind:'transcript',requestKey:key,filename:file.name,base64:fileBase64(bytes),language,permitted});setJob(d.job);if(d.job.status==='review')loadResult({...d.job.draft,filename:file.name,title});else setNotice(d.job.error||'Your transcription request is saved. Checking it will not submit another recording.');await refresh()}
 async function save(){const d=await workshopRequest('resources',{title,text,filename,language,...(job?.kind==='transcript'?{importJobId:job.id}:{}),...(url?{url}:{}),...(parent?{parentId:parent.id,parentChecksum:parent.checksum}:{})});
  // Adopt the saved source before retaining bytes; a failed file upload cannot
  // make the already saved text disappear or silently duplicate it.
  setSource(d.resource);setNotice(d.duplicate?'This exact text already exists; opening its saved source.':'Source text saved. Review the passages before using them.');
  if(retain&&file){try{await workshopRequest('knowledge/original/'+d.resource.id,{confirmed:true,checksum:d.resource.checksum,filename:file.name,base64:fileBase64(new Uint8Array(await file.arrayBuffer()))})}catch(e){setNotice('Text saved, but the original file was not retained. Keep your local file and retry from this form.');throw e}}
  await open(d.resource.id);setRevision(v=>v+1);
 }
 if(!author)return <SourceCollections client={client}/>;
 return <div className="knowledge-library"><header className="page-heading"><div><h1>Your source library</h1><p>Keep the evidence, find the idea, build the learning around it.</p></div><button className="primary" disabled={busy} onClick={()=>reset('edit')}>Add material</button></header>
 <nav className="knowledge-tabs" aria-label="Source library views"><button aria-pressed={mode==='browse'} disabled={busy} onClick={()=>setMode('browse')}>Sources</button><button aria-pressed={mode==='find'} disabled={busy} onClick={()=>setMode('find')}>Find evidence</button><button aria-pressed={mode==='imports'} disabled={busy} onClick={()=>run(async()=>{await refresh();setMode('imports')})}>Saved imports</button><button disabled={busy} aria-pressed={mode==='collections'} onClick={()=>setMode('collections')}>Collections</button></nav>
 <div aria-live="polite">{busy&&<p role="status">Working with your source material…</p>}{error&&<p role="alert" className="message error">{error}</p>}{notice&&<p className="message">{notice}</p>}</div>
 {mode==='chapter'&&selection&&<ChapterWorkshop request={selection} topic={{title:'Library evidence',goal:selection.goal,resources:[]}} client={client} onClose={()=>{setMode('find');setSelection(null)}}/>}
 {mode==='collections'&&<SourceCollections client={client}/>}
 {mode==='browse'&&<section className="surface"><LibraryPicker key={revision} linked={[]} disabled={busy} actionLabel="Open source" onPick={r=>run(()=>open(r.id))}/><p className="subtle">Source revisions are separate records. Already reviewed activities keep their exact evidence until you deliberately prepare a replacement.</p></section>}
 {mode==='find'&&<EvidenceFinder sources={[]} onPrepare={s=>{setSelection(s);setMode('chapter')}} disabled={busy}/>}
 {['edit','recording','url'].includes(mode)&&<section className="surface source-desk"><div className="section-heading"><h2>{parent?'Add a new version of '+parent.title:'Bring your learning material together'}</h2><button disabled={busy} onClick={()=>setMode('browse')}>Back to sources</button></div><div className="source-import-actions"><label>Upload a document or recording<input type="file" accept={DOCUMENT_ACCEPT+','+RECORDINGS} disabled={busy} onChange={e=>{const f=e.target.files?.[0];if(f)void run(()=>selectFile(f));e.target.value=''}}/></label><button disabled={busy} onClick={()=>{setMode('url');setJob(null);setFile(null);setText('');setFilename('');setPermitted(false)}}>Import a web page</button></div>
 <p className="subtle">Text, PDF, Word, slides, spreadsheets, captions, printed images and recordings. Up to 8 MB per file. Extracted text is editable before it becomes a source.</p><label className="check"><input type="checkbox" disabled={busy} checked={ocr} onChange={e=>setOCR(e.target.checked)}/>Read printed scans with English OCR (PDFs up to 12 pages). Leave off for normal PDF text; images always use OCR.</label>
 {mode==='url'&&<div className="source-url"><label>Public source URL<input type="url" value={url} maxLength={2000} onChange={e=>setURL(e.target.value)}/></label><p>Enabled hosts: {settings?.hosts?.join(', ')||'Checking…'}. Pages requiring sign-in are not imported.</p><label className="check"><input type="checkbox" checked={permitted} onChange={e=>setPermitted(e.target.checked)}/>I have permission to use this web material.</label><button disabled={busy||!permitted||!url} onClick={()=>run(async()=>loadResult(await workshopRequest('knowledge/url',{url,permitted})))}>Fetch text for review</button></div>}
 {mode==='recording'&&<div className="source-recording"><h3>{file?.name}</h3><p>Send the first audio track to Fish Transcribe 1 Pro. It transcribes speech; it does not interpret video images. One AI request is used, with a duration-based cost estimate. No automatic retry after a lost response.</p><label>Language hint (optional two-letter code)<input maxLength={2} value={language} onChange={e=>setLanguage(e.target.value.toLowerCase())} placeholder="en"/></label><label className="check"><input type="checkbox" checked={permitted} onChange={e=>setPermitted(e.target.checked)}/>I have permission to upload this recording and send its audio for transcription.</label><button disabled={busy||!permitted||!settings?.transcription||!!job} onClick={()=>run(transcribe)}>Transcribe for review</button>{job&&<button disabled={busy} onClick={()=>run(async()=>{const d=await workshopRequest('knowledge/jobs/'+job.id);setJob(d.job);if(d.job.draft)loadResult({...d.job.draft,filename:job.filename});else setNotice(d.job.error||'No completed transcript is available yet. No new request was sent.')})}>Check saved request</button>}</div>}
 {mode==='edit'&&<><label>Source title<input maxLength={160} value={title} onChange={e=>setTitle(e.target.value)}/></label><label>Source language<input maxLength={60} value={language} onChange={e=>setLanguage(e.target.value)} placeholder="For example, English or Español"/></label>{warnings.map((w,i)=><p key={i} className="source-warning">{w}</p>)}<label>Check and correct the source text<textarea rows={16} maxLength={60000} value={text} onChange={e=>setText(e.target.value)}/></label><p>Keep sheet, row, page and time labels where available. Write checked descriptions of diagrams and equations that extraction cannot explain.</p>{file&&<label className="check"><input type="checkbox" disabled={!settings?.originals} checked={retain} onChange={e=>setRetain(e.target.checked)}/>Keep this original file privately with this source version. It follows this source’s deletion and retention controls.</label>}<button className="primary" disabled={busy||title.trim().length<1||text.trim().length<60} onClick={()=>run(save)}>Save and review passages</button></>}
 </section>}
 {mode==='source'&&source&&<section className="surface source-reader"><div className="section-heading"><div><h2>{source.title}</h2><p>{source.status==='reviewed'?'Reviewed source':'Needs review'} · {source.units.length} passages{source.provenance?.language?' · '+source.provenance.language:''}</p></div><button disabled={busy} onClick={()=>reset('edit',source)}>Add revised version</button></div>{source.provenance?.url&&<p>Imported from <a href={source.provenance.url} target="_blank" rel="noreferrer">the recorded web page</a>; later page changes do not change these saved passages.</p>}{source.original&&<button disabled={busy} onClick={()=>run(async()=>saveOriginal(source.original.filename,await originalBytes(source.id)))}>Download original ({(source.original.bytes/1048576).toFixed(1)} MB)</button>}
 <details><summary>Source versions ({versions.length})</summary>{versions.map(v=><div className="source-version" key={v.id}><span>{v.title} · {new Date(v.created).toLocaleDateString()} · {v.status}</span><button disabled={busy||v.id===source.id} onClick={()=>run(()=>open(v.id))}>{v.id===source.id?'Current view':'Open version'}</button></div>)}</details>
 {source.units.map(u=><article className="source-passage" key={u.id}><h3>{u.locator}</h3><p>{u.excerpt}</p></article>)}{source.status!=='reviewed'&&<><label className="check"><input type="checkbox" checked={reviewed} onChange={e=>setReviewed(e.target.checked)}/>I checked the extracted passages, numbers and omissions, and have permission to use this material.</label><button className="primary" disabled={busy||!reviewed} onClick={()=>run(async()=>{setSource((await workshopRequest('resources/'+source.id+'/review',{checksum:source.checksum,confirmed:true})).resource);setRevision(v=>v+1);setNotice('Source reviewed. It is available for evidence selection.')})}>Mark source reviewed</button></>}
 </section>}
 {mode==='imports'&&<section className="surface"><h2>Saved search and transcription requests</h2><p>Reopen a result without paying to generate it again. A missing acknowledgement is shown honestly.</p>{!settings?.jobs.length&&<p>No imports or search suggestions yet.</p>}{settings?.jobs.map(j=><article className="source-version" key={j.id}><div><strong>{j.query||j.filename}</strong><p>{j.kind==='search'?'Search suggestions':'Transcription'} · {j.status}</p>{j.error&&<p>{j.error}</p>}</div>{j.kind==='transcript'&&j.draft&&<button disabled={busy} onClick={()=>{setFile(null);setRetain(false);setParent(null);setURL('');setJob(j);loadResult({...j.draft,filename:j.filename})}}>Review transcript</button>}{j.kind==='search'&&<button disabled={busy} onClick={()=>setMode('find')}>Open evidence finder</button>}</article>)}</section>}
 </div>;
}
