import React,{useEffect,useRef,useState} from 'react';
import {workshopRequest} from './client.js';
export function SearchSuggestions({query,onUse}){
 const [job,setJob]=useState(null),[jobs,setJobs]=useState([]),[language,setLanguage]=useState(''),[selected,setSelected]=useState([]),[busy,setBusy]=useState(false),[error,setError]=useState('');const key=useRef(null),lock=useRef(false),alive=useRef(true);
 useEffect(()=>{key.current=null},[query]);
 const adopt=j=>{setJob(j);if(j.draft)setSelected(j.draft.alternatives)};
 const run=async fn=>{if(lock.current)return;lock.current=true;setBusy(true);setError('');try{await fn()}catch(e){if(alive.current)setError(e.message)}finally{lock.current=false;if(alive.current)setBusy(false)}};
 useEffect(()=>{alive.current=true;void run(async()=>{const d=await workshopRequest('knowledge');if(alive.current)setJobs(d.jobs.filter(j=>j.kind==='search'))});return()=>{alive.current=false}},[]);
 useEffect(()=>{if(job?.status!=='running'||busy||error)return;const timer=setTimeout(()=>void run(async()=>adopt((await workshopRequest('knowledge/jobs/'+job.id+'/check',{})).job)),2500);return()=>clearTimeout(timer)},[job,busy,error]);
 const create=async()=>{const r=await workshopRequest('knowledge/jobs',{kind:'search',query,language,requestKey:key.current||(key.current=crypto.randomUUID())});adopt(r.job);if(r.job.status==='queued')adopt((await workshopRequest('knowledge/jobs/'+r.job.id+'/run',{})).job);key.current=null;const d=await workshopRequest('knowledge');setJobs(d.jobs.filter(j=>j.kind==='search'))};
 return <details className="search-suggestions"><summary>Find related terms</summary><p>The AI can suggest synonyms, subject vocabulary or translations. Only your search and chosen source language are sent. Review the suggestions before using them; they are not evidence that a source covers the idea.</p><label>Source language (optional)<input value={language} maxLength={60} disabled={busy} onChange={e=>{setLanguage(e.target.value);key.current=null}} placeholder="For example, English or Español"/></label><button type="button" disabled={busy||query.trim().length<3} onClick={()=>run(create)}>Suggest search terms · 1 AI request</button>
 {jobs.length>0&&<label>Reopen saved suggestions<select disabled={busy} value={job?.id||''} onChange={e=>{const j=jobs.find(x=>x.id===e.target.value);if(j)adopt(j)}}><option value="">Choose a saved search</option>{jobs.map(j=><option key={j.id} value={j.id}>{j.query} — {j.status}</option>)}</select></label>}
 <div aria-live="polite">{busy&&<p>Checking saved search suggestions…</p>}{error&&<p role="alert">{error}</p>}</div>{job&&<><p>Suggestions for “{job.query}”: {job.status}</p>{job.error&&<p>{job.error}</p>}{['queued','running','starting','interrupted'].includes(job.status)&&<button type="button" disabled={busy} onClick={()=>run(async()=>adopt((await workshopRequest('knowledge/jobs/'+job.id+'/'+(job.status==='queued'?'run':'check'),{})).job))}>Check saved request</button>}{job.draft&&<><p>{job.draft.note}</p>{job.draft.alternatives.map(t=><label key={t}><input type="checkbox" checked={selected.includes(t)} onChange={e=>setSelected(e.target.checked?[...selected,t]:selected.filter(x=>x!==t))}/>{t}</label>)}<button type="button" disabled={busy||!selected.length} onClick={()=>onUse(selected.join('\n'))}>Use selected alternatives</button><p>Press “Find relevant passages” to run the free search. Original search words and alternative matches are labelled separately.</p></>}</>}
 </details>;
}
