import React,{useEffect,useRef,useState} from 'react';
import {AudioSequenceController,formatTime,downloadBlob,decodeAudioSequence,encodeWav} from './audio-playback.js';
import './podcast.css';
const LABEL={guide:'Mira',learner:'Kit'};
const initial={index:0,playing:false,loading:false,position:0,duration:0,rate:1,error:'',ready:[],ended:false};
function Host({kind,active}){return <span className={'podcast-host '+kind+(active?' is-speaking':'')} aria-hidden="true"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="48" fill={kind==='guide'?'#dce5a8':'#abc5eb'}/><path d="M18 100Q20 66 50 66T82 100" fill={kind==='guide'?'#5574ca':'#49644f'}/><path d="M32 42Q30 17 51 19Q76 22 71 49L68 70L33 69Z" fill="#2c3549"/><path d="M36 37Q48 46 66 34L67 51Q65 69 51 70Q36 66 35 50Z" fill={kind==='guide'?'#b77e60':'#e3af8e'}/><path d={kind==='guide'?'M34 42Q36 16 56 24L70 39Q55 32 48 33Q42 42 34 42':'M33 40L35 25L43 27L48 18L56 24L62 20L69 32L66 39L50 33Z'} fill="#2c3549"/><path d="M26 46Q24 20 50 19Q76 19 75 46" fill="none" stroke="#172b48" strokeWidth="6"/><rect x="22" y="42" width="10" height="20" rx="4" fill="#294dde"/><rect x="70" y="42" width="10" height="20" rx="4" fill="#294dde"/><path d="M45 48h1m14 0h1" stroke="#172b48" strokeWidth="3" strokeLinecap="round"/><path d={active?'M46 57Q52 65 58 57Z':'M47 58Q52 61 57 58'} fill={active?'#613d3a':'none'} stroke="#613d3a" strokeWidth="2"/><path d="M74 60Q71 70 58 69" fill="none" stroke="#172b48" strokeWidth="3"/><rect x="54" y="66" width="9" height="6" rx="3" fill="#172b48"/></svg></span>;}
const safeName=title=>(title||'Mosaic episode').replace(/[^\p{L}\p{N} -]/gu,'').slice(0,70).trim()||'Mosaic episode';
export function PodcastPlayer({script,audioFor,onStatus=()=>{}}){
 const [state,setState]=useState(initial),[exporting,setExporting]=useState(false),[downloadError,setDownloadError]=useState(''),[answerVisible,setAnswerVisible]=useState(false);
 const controller=useRef(null),alive=useRef(false),status=useRef(onStatus),provider=useRef(audioFor);status.current=onStatus;provider.current=audioFor;
 const identity=JSON.stringify(script);
 useEffect(()=>{alive.current=true;setState(initial);setAnswerVisible(false);setDownloadError('');setExporting(false);const player=new AudioSequenceController({segments:script.segments,audioFor:(...args)=>provider.current(...args),onChange:setState});controller.current=player;return()=>{alive.current=false;player.dispose();};},[identity]);
 const current=script.segments[state.index],active=state.playing?current?.speaker:null;
 const transcript=()=>[script.title,script.summary,'AI narration of a reviewed script.','',...script.segments.flatMap((s,i)=>[`${i+1}. ${LABEL[s.speaker]||s.speaker}`,s.text,...s.sourceRefs.map(id=>{const source=script.sources.find(x=>x.id===id);return source?`Source: ${source.title} — ${source.locator}\n${source.excerpt}`:''}),'']),'Pause and think',script.question.prompt,'',script.question.answer].join('\n');
 async function download(){
  if(exporting||!controller.current)return;const player=controller.current;setExporting(true);setDownloadError('');status.current('Preparing the episode download. Existing recordings are reused.');
  try{const blobs=await player.all(),{buffer}=await decodeAudioSequence(blobs);if(!alive.current||controller.current!==player)return;downloadBlob(encodeWav({channels:[buffer.getChannelData(0)],sampleRate:buffer.sampleRate}),safeName(script.title)+'.wav');status.current('Episode audio downloaded. Download the transcript for its exact sources.');}
  catch(e){if(alive.current&&controller.current===player)setDownloadError(e.message||'The audio download could not be prepared.');}
  finally{if(alive.current&&controller.current===player)setExporting(false);}
 }
 return <section className="podcast-player" aria-label="Personal podcast">
  <div className="podcast-deck">
   <div className="podcast-cover"><div className="podcast-hosts"><Host kind="guide" active={active==='guide'}/><span className="podcast-link" aria-hidden="true"><i/><i/><i/></span><Host kind="learner" active={active==='learner'}/></div><span className="podcast-cover-label">Two voices.<br/>Something at stake.</span><span className="podcast-cover-signature">Mosaic audio</span></div>
   <div className="podcast-console"><span className="podcast-format">Personal podcast</span><h2>{script.title}</h2><p>{script.summary}</p>
    <div className="podcast-now"><span>{state.ended?'Episode complete':`Passage ${state.index+1} of ${script.segments.length}`}</span><strong>{LABEL[current?.speaker]}</strong></div>
    <div className="podcast-transport"><button className="podcast-skip" aria-label="Previous passage" disabled={state.index===0} onClick={()=>controller.current?.open(state.index-1)}>‹</button><button className="podcast-play" onClick={()=>{if(state.playing||state.loading&&controller.current?.wanted)controller.current?.pause();else void controller.current?.play();}} aria-label={state.playing?'Pause podcast':state.loading&&controller.current?.wanted?'Pause when recording is ready':'Play podcast'}>{state.playing?<><span aria-hidden="true">Ⅱ</span>Pause</>:state.loading?<><span aria-hidden="true">…</span>{controller.current?.wanted?'Pause playback':'Preparing audio'}</>:<><span aria-hidden="true">▶</span>{state.ended?'Listen again':'Play'}</>}</button><button className="podcast-skip" aria-label="Next passage" disabled={state.index+1>=script.segments.length} onClick={()=>controller.current?.open(state.index+1)}>›</button><label className="podcast-speed">Speed<select value={state.rate} onChange={e=>controller.current?.setRate(Number(e.target.value))}>{[.75,1,1.25,1.5].map(rate=><option key={rate} value={rate}>{rate}×</option>)}</select></label></div>
    <label className="podcast-seek">Position in this passage<input type="range" min="0" max={state.duration||1} step=".1" value={Math.min(state.position,state.duration||1)} disabled={!state.duration||state.loading} onChange={e=>controller.current?.seek(Number(e.target.value))}/><span><span>{formatTime(state.position)}</span><span>{formatTime(state.duration)}</span></span></label>
    <p className="podcast-disclosure">AI voices read the approved script. Listen, pause or follow the full transcript below.</p>
   </div>
  </div>
  {(state.loading||state.error)&&<p className={'podcast-message'+(state.error?' error':'')} role={state.error?'alert':'status'}>{state.error||'Preparing this passage’s recording. Pausing stops playback; the recording request continues. You can read ahead while it is prepared.'}</p>}
  <div className="podcast-downloads"><button onClick={download} disabled={exporting}>{exporting?'Preparing audio download…':'Download episode audio'}</button><button onClick={()=>downloadBlob(new Blob([transcript()],{type:'text/plain;charset=utf-8'}),safeName(script.title)+'-transcript.txt')}>Download transcript and sources</button><span>{state.ready.length} of {script.segments.length} recordings ready in this window</span></div>
  {downloadError&&<p className="podcast-message error" role="alert">{downloadError}</p>}
  <div className="podcast-transcript"><div className="podcast-transcript-heading"><h3>Follow the story</h3><p>Choose any passage to listen from that point.</p></div>{script.segments.map((segment,i)=><article className={'podcast-passage'+(state.index===i?' is-current':'')} key={segment.id} aria-current={state.index===i?'true':undefined}><div className="podcast-passage-label"><button aria-label={`Listen to passage ${i+1}, ${LABEL[segment.speaker]}`} onClick={()=>controller.current?.open(i)}><span aria-hidden="true">{i+1}</span>{LABEL[segment.speaker]}</button>{state.index===i&&state.playing&&<span className="podcast-reading">Listening</span>}</div><div><p>{segment.text}</p>{segment.sourceRefs.length>0&&<details><summary>Sources for this passage</summary>{segment.sourceRefs.map(id=>{const source=script.sources.find(x=>x.id===id);return source?<blockquote key={id}><p>{source.excerpt}</p><cite>{source.title} — {source.locator}</cite></blockquote>:null;})}</details>}</div></article>)}</div>
  <section className="podcast-reflection"><h3>Before the next episode</h3><p>{script.question.prompt}</p><button aria-expanded={answerVisible} onClick={()=>{controller.current?.pause();setAnswerVisible(!answerVisible);}}>{answerVisible?'Hide the explanation':'Compare with the reviewed explanation'}</button>{answerVisible&&<div><p>{script.question.answer}</p>{script.question.sourceRefs.map(id=>{const source=script.sources.find(s=>s.id===id);return source?<blockquote key={id}><p>{source.excerpt}</p><cite>{source.title} — {source.locator}</cite></blockquote>:null;})}</div>}</section>
 </section>;
}
