import {cycleGameLocation} from './cycle-navigation.js';
import React,{useEffect,useRef,useState} from 'react';
import {draftHash} from '../game-modes/draft-engine.js';
import {activitiesOf} from './programme.js';
import {gameURL} from './client.js';
import {LOOP_STAGES,LOOP_LABELS,questionFocus} from './learning-loop.js';
import './learning-cycle.css';
import {AllowanceUsed} from './AllowanceLine.jsx';

const Sources=({sources})=><div className="cycle-sources">{sources.map(s=><blockquote key={s.id}><p>{s.excerpt}</p><cite>{s.title} — {s.locator}</cite></blockquote>)}</div>;
export function PracticeReview({job,busy,save,approve,activities=[]}){
 const [draft,setDraft]=useState(job.draft),[checked,setChecked]=useState(false);
 useEffect(()=>{setDraft(job.draft);setChecked(false)},[job.draftHash]);
 const change=next=>{setDraft(next);setChecked(false)};
 const question=(i,key,value)=>change({...draft,questions:draft.questions.map((q,n)=>n===i?{...q,[key]:value}:q)});
 return <section className="surface cycle-review"><span className="eyebrow">Review before learning</span><h2>Does each question earn its answer?</h2><p>Check factual support, answer choices and feedback. Each stage needs a different question. Reviewing the answer key means this cycle cannot establish an unseen first attempt.</p>
 <label>Cycle title<input value={draft.title} maxLength={120} onChange={e=>change({...draft,title:e.target.value})}/></label><label>Learning objective<textarea value={draft.objective} maxLength={240} onChange={e=>change({...draft,objective:e.target.value})}/></label><label>Explanation<textarea rows={5} value={draft.explanation} maxLength={1600} onChange={e=>change({...draft,explanation:e.target.value})}/></label>
 {draft.questions.map((q,i)=><details className="cycle-review-question" key={q.stage} open={i===0}><summary>{i+1}. {LOOP_LABELS[q.stage]}{questionFocus(q,activities)&&<span className="cycle-review-focus"> · Tests: {questionFocus(q,activities)}</span>}</summary><label>Question<textarea rows={3} maxLength={600} value={q.prompt} onChange={e=>question(i,'prompt',e.target.value)}/></label>{q.options.map((v,n)=><div key={n}><label>Choice {n+1}<input maxLength={240} value={v} onChange={e=>question(i,'options',q.options.map((s,k)=>k===n?e.target.value:s))}/></label><label>Feedback for choice {n+1}<textarea maxLength={700} value={q.feedback[n]} onChange={e=>question(i,'feedback',q.feedback.map((s,k)=>k===n?e.target.value:s))}/></label></div>)}<label>Correct choice<select value={q.answer} onChange={e=>question(i,'answer',Number(e.target.value))}>{q.options.map((v,n)=><option key={n} value={n}>{n+1}. {v}</option>)}</select></label><label>Hint<textarea maxLength={500} value={q.hint} onChange={e=>question(i,'hint',e.target.value)}/></label><Sources sources={draft.sources.filter(s=>q.sourceRefs.includes(s.id))}/></details>)}
 <button disabled={busy||JSON.stringify(draft)===JSON.stringify(job.draft)} onClick={()=>save(draft)}>Save question edits</button><label className="check"><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/>I checked the objective, four distinct questions, every answer and explanation against the sources.</label><button className="primary" disabled={busy||!checked||JSON.stringify(draft)!==JSON.stringify(job.draft)} onClick={approve}>Approve this learning cycle</button>
 </section>;
}
export function LearningCycle({item,unit,client,initialId,onSelect=()=>{},onBack,onMedia}){
 const {pack}=item,identity={packId:pack.id,contentHash:draftHash(pack)};
 const [jobs,setJobs]=useState([]),[id,setId]=useState(initialId||null),[focus,setFocus]=useState(unit.activityKeys[0]),[budget,setBudget]=useState(null),[view,setView]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[answer,setAnswer]=useState(undefined),[confidence,setConfidence]=useState('tentative'),[text,setText]=useState('');
 const questionHeading=useRef(null);
 const active=useRef(true),lock=useRef(false),requestKey=useRef(null),job=jobs.find(j=>j.id===id),stage=view?.route.stage;
 const request=body=>client.journal.request((item.readOnly&&!body?'loop/banks':'creative')+(body?'':'?'+new URLSearchParams({...identity,...(id?{selectedJob:id}:{})})),body?{...identity,...body}:undefined);
 const adopt=data=>{if(active.current){setJobs(data.jobs.filter(j=>j.kind==='practice'));setBudget(data.budget)}};
 const remember=(j,data)=>{const summary={bankId:j.id,bankHash:j.draftHash,...identity,activityKey:data.activityKey||j.activityKey,title:data.title,updated:Date.now(),stage:data.route.stage,dueAt:data.state.dueAt,waiting:!!data.route.waiting,needsSupport:data.route.needsSupport,reason:data.route.reason,attempts:data.state.answers.length};client.cycles=[summary,...(client.cycles||[]).filter(c=>c.bankId!==j.id)];setView(data);setText(data.state.teachBack)};
 const loop=async(j=job,action)=>{const data=await client.journal.request('loop'+(action?'':'?'+new URLSearchParams({bankId:j.id,bankHash:j.draftHash})),action?{bankId:j.id,bankHash:j.draftHash,expectedVersion:view.version,action}:undefined);if(active.current)remember(j,data)};
 const run=async fn=>{if(lock.current)return;lock.current=true;setBusy(true);setError('');try{await fn()}catch(e){if(active.current)setError(e.message)}finally{lock.current=false;if(active.current)setBusy(false)}};
 useEffect(()=>{active.current=true;if(client.journal.user)void run(async()=>adopt(await request()));return()=>{active.current=false}},[pack.id]);
 useEffect(()=>{setAnswer(undefined);setConfidence('tentative');questionHeading.current?.focus()},[stage,id,view?.route.needsSupport]);
 useEffect(()=>{setView(null);setError('');let cancelled=false;if(job?.status==='published'){void client.journal.request('loop?'+new URLSearchParams({bankId:job.id,bankHash:job.draftHash})).then(data=>{if(!cancelled&&active.current){setError('');remember(job,data);onSelect(job)}}).catch(e=>{if(!cancelled&&active.current)setError(e.message)});}return()=>{cancelled=true}},[id,job?.draftHash,job?.status]);
 useEffect(()=>{const pending=jobs.find(j=>['starting','running'].includes(j.status));if(!pending||error)return;const timer=setTimeout(()=>void run(async()=>adopt(await request({action:'check',id:pending.id}))),3500);return()=>clearTimeout(timer)},[jobs,busy,error]);
 const generate=async()=>{const data=await request({action:'create',kind:'practice',activityKey:focus,requestKey:requestKey.current||(requestKey.current=crypto.randomUUID())});adopt(data);requestKey.current=null;setId(data.jobId);adopt(await request({action:'run',id:data.jobId}));};
 if(!client.journal.user)return <section className="surface"><h2>A learning cycle that comes back with you.</h2><p>Sign in to save first answers, support and later questions across visits.</p><a href="/account.html" className="button primary">Sign in</a><button onClick={onBack}>Back to programme</button></section>;
 return <section className="learning-cycle"><button className="text-button" onClick={onBack}>Back to my programme</button><header className="cycle-heading"><span className="eyebrow">Your learning cycle</span><h2>Understand it. Use it. Come back to it.</h2><p>One relationship, four fresh questions, with room to get unstuck. Questions are optional; you can play at any time.</p><a className="text-button" href={job?.status==='published'?cycleGameLocation(gameURL(item),job.id,job.draftHash,identity):gameURL(item)}>Go straight to the game</a></header>
 <div className="cycle-columns"><div className="cycle-main">
 {!job&&!item.readOnly&&<section className="surface"><h3>Choose what deserves a closer look.</h3><label>Focus<select value={focus} onChange={e=>{setFocus(e.target.value);requestKey.current=null}}>{activitiesOf(pack).filter(a=>unit.activityKeys.includes(a.key)).map(a=><option value={a.key} key={a.key}>{a.label}</option>)}</select></label><p>Starting point: <strong>{unit.profile.level}</strong>. {unit.profile.interests.length?'Examples can connect to '+unit.profile.interests.slice(0,2).join(' and ')+'.':''}</p><p>{unit.profile.struggles||'A starting question helps choose the next support.'}</p><button className="primary" disabled={busy||!budget?.remaining} onClick={()=>run(generate)}>Create fresh questions</button><AllowanceUsed budget={budget}/><p className="subtle">One AI request. Your selected source, starting point, interests, goal and difficulty are sent to Meta’s AI service. Review the questions before use; free edits and answers do not use AI allowance.</p></section>}
 {!job&&item.readOnly&&<section className="surface"><h3>Your organiser’s reviewed question sets</h3><p>{busy?"Opening your assigned question sets…":jobs.length?"Choose a saved cycle to begin. Your answers and help requests are recorded in your own learning account.":"No question set is currently assigned for this programme focus. You can still open the game."}</p></section>}
 {error&&<div className="message error" role="alert"><p>{error}</p><button disabled={busy} onClick={()=>run(async()=>{adopt(await request());if(job?.status==='published')await loop()})}>Refresh saved cycle</button></div>}
 {job&&['queued','starting','running','failed','interrupted'].includes(job.status)&&<section className="surface"><h3>{job.status==='running'?'Writing your fresh questions…':'Your saved generation request'}</h3><p>{job.error||'You can leave this page and return. Checking resumes the same request.'}</p><button disabled={busy} onClick={()=>run(async()=>adopt(await request({action:job.status==='queued'?'run':'check',id:job.id})))}>{job.status==='queued'?'Start saved request':'Check saved request'}</button></section>}
 {job?.status==='review'&&job.draft&&<PracticeReview job={job} activities={activitiesOf(pack)} busy={busy} save={draft=>run(async()=>adopt(await request({action:'edit',id:job.id,draftHash:job.draftHash,draft})))} approve={()=>run(async()=>adopt(await request({action:'review',id:job.id,draftHash:job.draftHash,confirmed:true})))}/>}
 {job?.status==='published'&&!view&&!error&&<p role="status">Opening your saved questions…</p>}
 {view&&job?.status==='published'&&<><ol className="cycle-steps" aria-label="Learning cycle stages">{LOOP_STAGES.map((s,i)=><li key={s} aria-current={s===stage?'step':undefined} className={view.state.answers.some(a=>a.stage===s)?'recorded':''}><span>{i+1}</span>{LOOP_LABELS[s]}</li>)}</ol><section className="surface cycle-question"><span className="eyebrow">{stage==='complete'?'Cycle recorded':LOOP_LABELS[stage]}</span><h2 ref={view.question?null:questionHeading} tabIndex={-1}>{view.objective}</h2><p className="cycle-reason">{view.route.reason}</p>{view.profileChanged&&<p className="message">Your programme preferences changed. This reviewed cycle keeps its original wording. Create fresh questions to use your new preferences.</p>}
 {view.route.waiting&&<div className="cycle-date"><span>Next visit</span><strong>{new Date(view.route.dueAt).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}</strong><button disabled={busy} onClick={()=>run(()=>loop())}>Check whether it is due</button><p>{view.state.answers.some(a=>!view.answers.find(v=>v.stage===a.stage)?.correct||a.assisted||a.confidence!=='confident')?'One day after this practice because an answer or help suggests another look.':'Three days after this practice because the first three recorded answers were correct, confident and without in-cycle help.'}</p></div>}
 {view.question&&<><h3 ref={questionHeading} tabIndex={-1}>{view.question.prompt}</h3><fieldset><legend>Your answer</legend>{[...view.question.options,'I’m not sure yet.'].map((choice,i)=><label className={'answer '+(answer===(i===3?null:i)?'selected':'')} key={i}><input type="radio" name="cycle-answer" disabled={busy} checked={answer===(i===3?null:i)} onChange={()=>setAnswer(i===3?null:i)}/>{choice}</label>)}</fieldset><label>How confident do you feel?<select value={confidence} onChange={e=>setConfidence(e.target.value)}><option value="tentative">I am tentative</option><option value="confident">I can explain my answer</option><option value="not-sure">I am not sure</option></select></label>{view.question.hint&&<p className="note">{view.question.hint}</p>}<div className="form-actions"><button className="primary" disabled={busy||answer===undefined} onClick={()=>run(()=>loop(job,{type:'answer',stage,answer,confidence}))}>Record my answer</button><button disabled={busy} onClick={()=>run(()=>loop(job,{type:'help',stage,kind:'hint'}))}>Give me a clue</button></div></>}
 {stage!=='complete'&&<button disabled={busy} onClick={()=>run(()=>loop(job,{type:'help',stage,kind:'explanation'}))}>{view.explanation?'Read the explanation again':'Work through the explanation'}</button>}
 {view.explanation&&<section className="cycle-explanation"><h3>A different way into the idea.</h3><p>{view.explanation}</p><Sources sources={view.sources}/>{stage!=='complete'&&<><label>Explain it in your own words<textarea rows={3} maxLength={1600} value={text} onChange={e=>setText(e.target.value)}/></label><button disabled={busy||!text.trim()} onClick={()=>run(()=>loop(job,{type:'explain',text}))}>Save my explanation</button><p className="subtle">Your explanation is saved ungraded. Compare the reasoning with the sources.</p></>}</section>}
 {stage==='complete'&&!item.readOnly&&<button className="primary" onClick={()=>{setFocus(view.route.needsSupport?view.activityKey:unit.activityKeys.find(k=>!jobs.some(j=>j.activityKey===k&&j.status==='published'))||unit.activityKeys[0]);setId(null);setView(null);onSelect(null)}}>{view.route.needsSupport?'Prepare fresh practice for this focus':'Choose my next focus'}</button>}
 </section><section className="cycle-paths"><div><h3>Put it into play.</h3><p>Explore this exact reviewed chapter. A game win stays separate from these answers.</p><a className="button" href={cycleGameLocation(gameURL(item),job.id,job.draftHash,identity)}>Open the game</a><p className="subtle">Use “Return to learning” in the game to continue this saved question cycle.</p></div><div><h3>Find another way in.</h3><p>Talk it through, listen to a podcast or watch an explanation.</p><button onClick={onMedia}>Open creative learning</button></div></section><section className="surface"><h3>Your evidence, step by step.</h3>{view.answers.length?view.answers.map(a=><article className="cycle-observation" key={a.stage}><span className="badge">{LOOP_LABELS[a.stage]}</span><h4>{a.prompt}</h4><p>{a.choice} · {a.correct?'Correct on this question':'Worth another look'}</p><p>{a.feedback}</p><small>{a.assisted?'Tutor or activity help was recorded.':'No tutor or activity help was recorded for this response.'} Confidence: {a.confidence}. {new Date(a.at).toLocaleString()}</small></article>):<p>Your first answer will appear here. Earlier attempts cannot be replaced.</p>}<p className="subtle">These are practice observations, not a grade or mastery score. {job.readOnly?'Your organiser reviewed this question set.':'You reviewed this question bank before use.'} Other help is not detectable.</p></section></>}
 </div><aside className="cycle-sidebar"><h3>Saved cycles</h3>{!item.readOnly&&<><p>{budget?`${budget.remaining} AI requests available`:'Checking allowance…'}</p>{budget&&<a className="allowance-link" href="/welcome.html#allowance">Need more? Ask for a higher allowance</a>}<button disabled={busy} onClick={()=>{setId(null);setView(null);onSelect(null)}}>Plan a fresh cycle</button></>}{jobs.map(j=><button className={id===j.id?'selected':''} disabled={busy} key={j.id} onClick={()=>{setId(j.id);if(j.status!=='published')onSelect(null)}}><strong>{j.draft?.title||'Questions being prepared'}</strong><span>{j.status}</span></button>)}{!jobs.length&&<p>Reviewed questions and your attempts will stay with this programme version.</p>}<p className="subtle">Help, confidence and first answers are kept distinct. Timing is a fixed practice rule; no ability label is assigned.</p></aside></div></section>;
}
