 {q.hint&&<p className="explore-clue">{q.hint}</p>}{!saved&&<div className="form-actions"><button className="primary" disabled={busy||!response.trim()||q.type==='worked-solution'&&!working.trim()} onClick={()=>onAction({type:'answer',id:q.id,response,unit,working,confidence,criteria})}>Save my first response</button><button disabled={busy||help} onClick={()=>onAction({type:'help',id:q.id})}>Give me a clue</button></div>}
 {saved&&<section className="explore-saved-response" aria-label="Your saved first response"><h4>Your saved first response</h4><p>{saved.response} {saved.unit}</p>{saved.working&&<p>{saved.working}</p>}<p>Confidence: {saved.confidence}</p>{q.criteria.length>0&&<ul>{q.criteria.map((c,i)=><li key={i}>{c.label}: {saved.criteria[i]}</li>)}</ul>}</section>}{saved&&<section className="explore-feedback" aria-label="Response feedback"><h4>{q.result.status==='human-review'?'Use the rubric to review your response':q.result.status==='result-matched'?'Your final value matches. Now check the reasoning.':q.result.correct?'Your answer matches the reviewed key.':q.result.status==='check-unit'?'Check the unit as well as the value.':q.result.status==='invalid-number'?'Use a decimal number, with the unit in its separate field.':'Compare your answer with the reviewed explanation.'}</h4><p>{q.explanation}</p>{q.type==='short-answer'&&<p>Accepted short answers: {q.accepted.join('; ')}. A different valid wording may need human review; exact matching cannot judge meaning.</p>}{['numeric','worked-solution'].includes(q.type)&&<p>Reviewed final value: {fmt(q.answer)} {q.unit}</p>}{q.steps?.length>0&&<ol>{q.steps.map((s,i)=><li key={i}>{s}</li>)}</ol>}{q.criteria.map((c,i)=><div key={i}><strong>{c.label}</strong><p>{saved.criteria[i]==='shown'?'You marked this as shown. Check that your actual words provide the evidence.':c.improve}</p></div>)}<p className="subtle">{saved.assisted?'A clue was used before this response.':'No in-task clue was recorded.'} {q.type==='rubric'||q.type==='worked-solution'?'Reasoning needs human judgment; no automatic grade is assigned.':'This is practice feedback, not a grade or mastery judgment.'}</p></section>}
