import React,{useEffect,useRef,useState} from 'react';
import './teacher-review.css';
import {FeedbackStarters,addStarter} from './feedback-starters.jsx';
export function TeacherReview({assignment:g,client,teacher=false,onChange}){
 const [open,setOpen]=useState(false),[data,setData]=useState(null),[selected,setSelected]=useState(''),[ids,setIds]=useState([]),[consent,setConsent]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[strength,setStrength]=useState(''),[nextStep,setNextStep]=useState('');
 const serial=useRef(0),identity=client.journal.user?.id;
 const base={id:g.id,revision:g.revision};
 async function load(lessonId=selected){const n=++serial.current;setBusy(true);setError('');try{const r=data?.lessons.find(l=>l.id===lessonId),v=await client.journal.request('teacher-review?'+new URLSearchParams({...base,...(r?{lessonId:r.id,lessonHash:r.hash}:{})}));if(n!==serial.current||identity!==client.journal.user?.id)return;setData(v);setStrength(v.feedback?.strength||'');setNextStep(v.feedback?.nextStep||'');setIds([]);setConsent(false);}catch(e){if(n===serial.current)setError(e.message)}finally{if(n===serial.current)setBusy(false)}}
 useEffect(()=>()=>{serial.current++},[identity,g.revision]);
 async function action(body){if(busy)return;setBusy(true);setError('');setNotice('');try{await client.journal.request('teacher-review',{...base,...body});if(identity!==client.journal.user?.id)return;await load();await onChange?.();setNotice(body.action==='feedback'?'Feedback sent to the learner.':body.action==='withdraw'?'Your work is no longer shared.':'Your selected work was sent for feedback.');}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <section className="teacher-review"><button className="tr-open" aria-expanded={open} onClick={()=>{setOpen(v=>!v);if(!open)void load()}}>{teacher?'Review submitted work':'Send work for feedback'}</button>{open&&<div className="tr-body"><header><span>{teacher?'TEACHER REVIEW':'YOUR WORK, YOUR CHOICE'}</span><h4>{teacher?'Read the reasoning. Guide the next step.':'Choose the answers your organiser sees.'}</h4></header><p>{teacher?'Only responses the learner explicitly submitted appear here. Give formative feedback; this does not award a grade.':'Your organiser sees only the selected answers below, any working and whether help was used. Your other answers, interests and conversations stay private.'}</p>
 {busy&&<p role="status">Checking current work and permissions…</p>}{error&&<p role="alert">{error}</p>}{notice&&<p role="status">{notice}</p>}
 {!teacher&&data&&<fieldset disabled={busy}><legend>Select saved Explore work</legend><label>Lesson<select value={selected} onChange={e=>{setSelected(e.target.value);void load(e.target.value)}}><option value="">Choose a lesson</option>{data.lessons.map(l=><option key={l.id} value={l.id}>{l.title}</option>)}</select></label>{selected&&!busy&&!data.pending.length&&<p>No saved answers in this lesson yet. Open its Explore activity and save your responses first.</p>}{data.pending.map(a=><label className="tr-choice" key={a.id}><input type="checkbox" checked={ids.includes(a.id)} onChange={e=>{setIds(v=>e.target.checked?[...v,a.id]:v.filter(id=>id!==a.id));setConsent(false)}}/><span><b>{a.prompt}</b><span>{a.response} {a.unit}</span>{a.working&&<span>Working: {a.working}</span>}<small>{a.assisted?'Help was used':'No recorded hint'}</small></span></label>)}{!!ids.length&&<><label className="check"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/>Send these {ids.length} selected answers to {g.className?'my teacher for '+g.className:'my current organiser'}.</label><button className="primary" disabled={!consent} onClick={()=>action({action:'submit',lessonId:selected,lessonHash:data.lessons.find(l=>l.id===selected).hash,answerIds:ids,confirmed:true,pendingVersion:data.pendingVersion,token:data.token})}>Send selected work</button></>}</fieldset>}
 {data&&!data.sharing&&<p>No work is currently shared for this assignment.</p>}{data?.submission&&<div className="tr-columns"><div><h5>Submitted work</h5><p className="tr-caption">Sent {new Date(data.submission.submittedAt).toLocaleString()} · exact lesson version {data.submission.lessonHash.slice(0,8)}</p>{data.submission.answers.map(a=><article key={a.id}><h5>{a.prompt}</h5><p className="tr-response">{a.response} {a.unit}</p>{a.working&&<p>{a.working}</p>}<small>{a.assisted?'Hint used before answering':'No recorded hint'}</small></article>)}<details><summary>Reviewed source evidence and criteria</summary>{data.lesson.sources.map(s=><blockquote key={s.id}>{s.excerpt||s.text}<cite>{s.id}</cite></blockquote>)}{data.lesson.assessment.filter(q=>data.submission.answers.some(a=>a.id===q.id)).map(q=><p key={q.id}><b>{q.prompt}</b><br/>{q.explanation}{q.criteria.map(c=><span key={c.label}><br/>{c.label}: {c.evidence}</span>)}</p>)}</details></div><div><h5>Feedback from your organiser</h5>{teacher?<fieldset disabled={busy}><legend>Help this learner move forward</legend><label>What the reasoning shows<textarea value={strength} maxLength={1200} onChange={e=>setStrength(e.target.value)} /></label><label>A useful next step<textarea value={nextStep} maxLength={1200} onChange={e=>setNextStep(e.target.value)} /></label><FeedbackStarters disabled={busy} onStrength={line=>setStrength(v=>addStarter(v,line).slice(0,1200))} onNext={line=>setNextStep(v=>addStarter(v,line).slice(0,1200))}/><button className="primary" disabled={!strength.trim()||!nextStep.trim()} onClick={()=>action({action:'feedback',submissionHash:data.submissionHash,expectedVersion:data.feedbackVersion,strength,nextStep})}>Send formative feedback</button></fieldset>:data.feedback?<><p>{data.feedback.strength}</p><p><b>Next step</b><br/>{data.feedback.nextStep}</p></>:<p>Waiting for your organiser’s review.</p>}{!teacher&&<><button disabled={busy} onClick={()=>action({action:'withdraw'})}>Stop sharing this work</button><p className="tr-caption">Stops access immediately. Your saved copy remains in Your data until deleted or expired.</p></>}</div></div>}
 <button disabled={busy} onClick={()=>load()}>Refresh work and feedback</button></div>}</section>
}
