import React,{useEffect,useRef,useState} from 'react';
import {mediaJobLabel,MEDIA_STYLES} from './creative-content.js';
export function MediaJobs({job,client}){
 const [data,setData]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[style,setStyle]=useState('anime'),[story,setStory]=useState([]),[useStory,setUseStory]=useState(true);
 const identity=client.journal.user?.id,scope=useRef(0);
 async function load(){const n=scope.current,r=await client.journal.request('media-jobs?'+new URLSearchParams({scriptId:job.id}));if(n===scope.current&&client.journal.user?.id===identity)setData(r);
  // Approved story backdrops can be used in the video; without them the standard settings are used.
  if(job.kind==='cartoon'){const b=await client.journal.request('creative/backdrops?'+new URLSearchParams({scriptId:job.id})).catch(()=>null);if(n===scope.current)setStory((b?.sets||[]).filter(s=>s.status==='approved').map(s=>s.style))}}
 useEffect(()=>{scope.current++;setData(null);setError('');setBusy(false);let active=true;const update=()=>{if(active)void load().catch(e=>active&&setError(e.message))};update();const timer=setInterval(update,10000);return()=>{active=false;scope.current++;clearInterval(timer)}},[job.id,identity]);
 async function act(body){const n=scope.current;setBusy(true);setError('');try{await client.journal.request('media-jobs',body);if(n===scope.current)await load()}catch(e){if(n===scope.current)setError(e.message)}finally{if(n===scope.current)setBusy(false)}}
 async function download(item){setBusy(true);try{const r=await fetch('/api/learning/data',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Mosaic-Learner':identity,'X-Mosaic-Data-Epoch':client.journal.dataEpoch||'0:0'},body:JSON.stringify({action:'download',id:item.assetId,epoch:client.journal.dataEpoch||'0:0'})});if(!r.ok)throw Error((await r.json()).error||'Saved media unavailable');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='mosaic-episode.'+item.format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <section className="background-media"><h4>Prepare a saved episode</h4><p>Preparation continues when you close this tab. Existing narration is reused; missing clips use your voice allowance. The completed file is stored privately and follows Your data retention settings.</p>{error&&<p role="alert">{error}</p>}{job.kind==='cartoon'&&<label>Video artwork<select value={style} onChange={e=>setStyle(e.target.value)} disabled={busy}>{Object.entries(MEDIA_STYLES).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label>}{job.kind==='cartoon'&&story.includes(style)&&<label className="check"><input type="checkbox" checked={useStory} disabled={busy} onChange={e=>setUseStory(e.target.checked)}/>Use the approved backdrops made for this story</label>}<button disabled={busy||!data?.workerEnabled} onClick={()=>act({action:'create',scriptId:job.id,scriptHash:job.draftHash,format:job.kind==='cartoon'?'mp4':'mp3',style,edition:useStory&&story.includes(style)?3:0})}>{job.kind==='cartoon'?'Prepare narrated MP4':'Prepare podcast MP3'}</button>{data&&!data.workerEnabled&&<p>Background preparation is not connected yet.</p>}<ul>{data?.jobs.map(r=><li key={r.id}><b>{mediaJobLabel(r)}</b><span> {r.status} · {r.done}/{r.total} narration clips</span>{r.error&&<p>{r.error}</p>}{r.status==='complete'?<button disabled={busy} onClick={()=>download(r)}>Download saved {r.format.toUpperCase()}</button>:['failed','cancelled'].includes(r.status)?<button disabled={busy} onClick={()=>act({action:'retry',id:r.id})}>Retry with saved narration</button>:<button disabled={busy} onClick={()=>act({action:'cancel',id:r.id})}>Cancel preparation</button>}</li>)}</ul><p className="subtle">Cancelling stops further preparation. Already generated clips remain available until deleted or expired. <a href="/studio#data">Manage saved media</a></p></section>
}
export function OperationsHealth({client}){
 const [data,setData]=useState(null),[error,setError]=useState('');
 async function load(){try{setData(await client.journal.request('operations'));setError('')}catch(e){setError(e.message)}}
 return <details className="background-media" onToggle={e=>{if(e.currentTarget.open)void load()}}><summary>Service health · administrator</summary>{error&&<p role="alert">{error}</p>}{data&&<><p role={data.attention?'alert':'status'}>{data.attention?'Some operations need attention. ':'All checked services are current. '}</p><p>{data.stale?'Media worker needs attention.':'Media worker is responding.'} Last heartbeat: {data.lastHeartbeat?new Date(data.lastHeartbeat).toLocaleString():'Not received'}.</p><ul>{data.queue.map(q=><li key={q.status}>{q.status.replace('media-','')}: {q.count}</li>)}</ul><p>{data.retention?'Retention last reported '+new Date(data.retention.at).toLocaleString()+'.':'No retention completion has been recorded.'}</p></>}<button onClick={load}>Refresh service health</button></details>
}
