import React,{useEffect,useRef,useState} from 'react';
import {draftHash} from '../game-modes/draft-engine.js';
import {PROGRAMME_FORMATS,FORMAT_LABELS} from './connected-programme.js';
import {PodcastPlayer} from './media/PodcastPlayer.jsx';
import {CartoonPlayer} from './media/CartoonPlayer.jsx';
import {cycleGameLocation} from './cycle-navigation.js';
import {gameURL} from './client.js';
import './connected-programme.css';
import './voice-tutor.css';
const names={explore:'Explore lesson',practice:'Question cycle',podcast:'Podcast',cartoon:'Cartoon'};
export function ConnectedProgramme({item,unit,client,onOpen}){
 const [data,setData]=useState(null),[draft,setDraft]=useState(null),[editing,setEditing]=useState(false),[media,setMedia]=useState(null),[reflection,setReflection]=useState(''),[used,setUsed]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');const lock=useRef(false),alive=useRef(true);
 const identity={packId:item.pack.id,contentHash:draftHash(item.pack)},params=new URLSearchParams(identity);
 const request=body=>client.journal.request('programme'+(body?'':'?'+params),body?{...identity,...body}:undefined);
 const load=async()=>{const d=await request();if(alive.current){setData(d);if(!editing)setDraft(d.state)}};
 const run=async fn=>{if(lock.current)return;lock.current=true;setBusy(true);setError('');setNotice('');try{await fn()}catch(e){if(alive.current)setError(e.message)}finally{lock.current=false;if(alive.current)setBusy(false)}};
 useEffect(()=>{alive.current=true;if(client.journal.user)void run(load);return()=>{alive.current=false}},[unit.id]);
 const practiceLink=data?.route.steps.find(s=>s.kind==='practice')?.resource,chapterURL=practiceLink?cycleGameLocation(gameURL(item),practiceLink.id,practiceLink.hash,identity):gameURL(item);
 const open=step=>run(async()=>{if(['podcast','cartoon'].includes(step.kind)&&step.resource){const d=await client.journal.request('programme?'+new URLSearchParams({...identity,resourceId:step.resource.id,resourceHash:step.resource.hash}));if(alive.current){setMedia({...step.resource,kind:step.kind,script:d.script,backdrops:d.backdrops||[]});setReflection(step.reflection);setUsed(step.done)}}else onOpen(step.kind,step.resource)});
 const audioFor=async(segment,index)=>{const account=client.journal.user.id,r=await fetch('/api/learning/programme?'+new URLSearchParams({...identity,resourceId:media.id,resourceHash:media.hash,audioIndex:String(index)}),{credentials:'same-origin',cache:'no-store',headers:{'X-Mosaic-Learner':account}});if(!r.ok){const d=await r.json();throw Error(d.error||'Saved narration unavailable.')}const blob=await r.blob();if(client.journal.user?.id!==account)throw Error('Your account changed. Reopen the programme.');return blob;};
 const backdropFor=async(style,scene)=>{const account=client.journal.user.id,r=await fetch('/api/learning/programme?'+new URLSearchParams({...identity,resourceId:media.id,resourceHash:media.hash,backdrop:scene,backdropStyle:style}),{credentials:'same-origin',cache:'no-store',headers:{'X-Mosaic-Learner':account}});if(!r.ok)throw Error('Backdrop unavailable.');if(client.journal.user?.id!==account)throw Error('Your account changed. Reopen the programme.');return r.blob();};
 if(!client.journal.user)return <section className="surface"><h2>Connect your learning formats</h2><p>Sign in to keep a reviewed programme and your format choices across visits.</p><a href="/account.html">Sign in</a></section>;
 return <section className="connected-programme" aria-labelledby="connected-programme-heading"><header className="connected-heading"><div><h2 id="connected-programme-heading">One idea. A connected learning journey.</h2><p>{unit.profile.goal||item.pack.title}</p></div><button disabled={busy||!data} onClick={()=>{setEditing(!editing);setDraft(data.state)}}>{editing?'Close choices':'Choose formats and resources'}</button></header>
 <div aria-live="polite">{busy&&<p role="status">Opening your learning programme…</p>}{error&&<div className="message error" role="alert"><p>{error}</p><button disabled={busy} onClick={()=>run(load)}>Refresh saved programme</button></div>}{notice&&<p className="message">{notice}</p>}</div>
 {data&&<><div className="connected-reason"><p><strong>Your next step:</strong> {data.route.next?FORMAT_LABELS[data.route.next]:'Choose a fresh objective or revisit your reflection.'}</p><p>{data.route.reason}</p><small>Planned for about {data.route.minutes} minutes. {data.route.interest.length?'Your chosen interests: '+data.route.interest.join(' and ')+'. ':''}You can open any available step or choose another format.</small></div>
 {data.adaptive&&<section className="adaptive-focus" aria-label="Your learning support"><h3>Support for your next step</h3><p className="focus-label">{data.adaptive.focus[0]?.label}</p><p>{data.adaptive.focus[0]?.reason}</p>{data.adaptive.focus[0]?.pointToRevisit&&<p><strong>Point to revisit: </strong>{data.adaptive.focus[0].pointToRevisit}</p>}<label>How much support would you like?<select value={data.adaptive.choice} disabled={busy} onChange={e=>{const supportChoice=e.target.value;void run(async()=>{const d=await request({action:'support-choice',supportChoice,expectedVersion:data.version});setData(d);setDraft(d.state);setNotice('Support preference saved. Your original responses are unchanged.')})}}><option value="suggested">Use the suggested support</option><option value="more">More explanation and worked steps</option><option value="less">Let me try with fewer prompts</option></select></label><p><button disabled={busy} onClick={()=>onOpen('tutor',{activityKey:data.adaptive.nextFocus})}>Talk this through with the tutor</button></p><details><summary>How this suggestion was made</summary><p>{data.adaptive.scope}</p><ul>{data.adaptive.focus.map(f=><li key={f.key}><strong>{f.label}</strong>: {f.reason} {f.observations} distinct first responses considered.</li>)}</ul><p>These suggestions guide the order of your activities and the tutor’s next explanation. Your chosen interests provide examples; they do not change the source facts. Refresh after practice to see updated suggestions.</p></details></section>}
 {editing&&draft&&<section className="connected-choices" aria-label="Programme choices"><h3>Choose the ways into this idea</h3><p>Link exact approved versions. Choosing your programme formats uses no AI allowance. Missing resources can be prepared and reviewed from the tools below.</p>{PROGRAMME_FORMATS.map(kind=><div className="connected-choice" key={kind}><label className="check"><input type="checkbox" checked={draft.formats.includes(kind)} onChange={e=>setDraft({...draft,formats:e.target.checked?[...draft.formats,kind]:draft.formats.filter(k=>k!==kind)})}/>{names[kind]}</label><label>Reviewed {names[kind].toLowerCase()}<select value={(()=>{const l=draft.links.find(l=>l.kind===kind);return l?l.id+':'+l.hash:''})()} onChange={e=>{const r=data.resources.find(r=>r.id+':'+r.hash===e.target.value&&r.kind===kind);setDraft({...draft,links:[...draft.links.filter(l=>l.kind!==kind),...(r?[{id:r.id,hash:r.hash,kind}]:[])]})}}><option value="">Choose a reviewed resource</option>{draft.links.filter(l=>l.kind===kind&&!data.resources.some(r=>r.id===l.id&&r.hash===l.hash)).map(l=><option key={l.id+':'+l.hash} value={l.id+':'+l.hash} disabled>Linked version unavailable — choose a reviewed replacement</option>)}{data.resources.filter(r=>r.kind===kind).map(r=><option key={r.id+':'+r.hash} value={r.id+':'+r.hash}>{r.title}{r.assigned?' · assigned':''}</option>)}</select></label></div>)}<button className="primary" disabled={busy} onClick={()=>run(async()=>{const d=await request({action:'choose',expectedVersion:data.version,formats:draft.formats,links:draft.links});setData(d);setDraft(d.state);setEditing(false);setNotice('Programme choices saved. Existing learning records are unchanged.')})}>Save my programme choices</button></section>}
 {!media?<ol className="learning-itinerary">{data.route.steps.map((step,i)=><li key={step.kind} className={data.route.next===step.kind?'is-next':''}><span className="itinerary-number" aria-hidden="true">{i+1}</span><div className="itinerary-copy"><h3>{step.title}</h3><p>{step.resource?.title||({read:'Read the exact passages behind your selected focus.',game:item.pack.title,reflect:'Explain the idea using one of your interests, then check where the comparison stops working.'}[step.kind])||(step.unavailable?'The linked version is unavailable. Choose a current reviewed resource.':'Choose or prepare a reviewed '+names[step.kind].toLowerCase()+'.')}</p>{step.resource?.broaderFocus&&<p className="subtle">This story also covers other ideas in this chapter.</p>}<small>{step.selfReported&&step.done?'You reported using this episode.':step.progress?.waiting?'Later question opens '+new Date(step.progress.dueAt).toLocaleString():step.done?'Activity recorded; not a mastery judgment.':step.progress?.attempts?step.progress.attempts+(step.progress.attempts===1?' first response recorded.':' first responses recorded.'):'At your pace.'}</small>{step.progress?.needsSupport&&<p className="itinerary-support">Revisit the explanation and compare your reasoning with the source.</p>}{step.progress?.humanReview&&<p>Written reasoning needs human review.</p>}</div><div className="itinerary-actions">{step.kind==='game'?<a className="button" href={chapterURL}>Play chapter</a>:<button disabled={busy||step.unavailable||item.readOnly&&PROGRAMME_FORMATS.includes(step.kind)&&!step.resource} onClick={()=>open(step)}>{step.resource||!PROGRAMME_FORMATS.includes(step.kind)?'Open '+({read:'sources',reflect:'reflection'}[step.kind]||names[step.kind].toLowerCase()):'Prepare '+names[step.kind].toLowerCase()}</button>}{PROGRAMME_FORMATS.includes(step.kind)&&!step.resource&&<button className="text-button" onClick={()=>{setEditing(true);setDraft(data.state)}}>Choose saved resource</button>}</div></li>)}</ol>:<section className="connected-media"><button onClick={()=>{setMedia(null);setNotice('')}}>Back to my learning journey</button>{media.kind==='podcast'?<PodcastPlayer script={media.script} audioFor={audioFor} onStatus={setNotice}/>:<CartoonPlayer script={media.script} audioFor={audioFor} backdrops={{sets:media.backdrops,load:backdropFor}} onStatus={setNotice} reducedMotion={unit.profile.access.reducedMotion} captions={unit.profile.access.captions!==false}/>}
 <p>Playback here uses saved narration only. If audio is missing, the transcript remains available. {item.readOnly?'Ask your organiser to prepare narration.':'Use Creative learning to prepare any missing narration.'}</p><label className="check"><input type="checkbox" checked={used} onChange={e=>setUsed(e.target.checked)}/>I used this episode or its transcript. This is a personal activity note, not a learning score.</label><label>What changed in your understanding?<textarea rows={4} maxLength={2000} value={reflection} onChange={e=>setReflection(e.target.value)}/></label><button disabled={busy} className="primary" onClick={()=>run(async()=>{const d=await request({action:'reflect-media',expectedVersion:data.version,id:media.id,hash:media.hash,used,reflection});setData(d);setNotice('Your activity note and reflection are saved, ungraded.')})}>Save episode reflection</button></section>}
 <footer className="connected-footer"><p>{data.route.scope} Your records stay private unless you explicitly share an existing course update.</p><button disabled={busy} onClick={()=>run(load)}>Refresh activity progress</button></footer></>}
 </section>;
}
