 const inUnits=new Set(client.state.units.map(u=>u.packId)),free=(client.journal.records||[]).filter(r=>r.summary&&!inUnits.has(r.summary.packId)).sort((a,b)=>b.updated-a.updated).slice(0,12);
 const when=ms=>new Date(ms).toLocaleDateString('en-GB',{day:'numeric',month:'short'});
 return <>{explore?.length>0&&<section className="surface trail-section"><div className="section-heading"><div><p className="trail-kicker">Explore</p><h2>Explore lessons</h2></div></div><ul className="trail-extra">{explore.map((l,i)=><li key={l.lessonId} style={{'--i':i}}><span className="te-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="28" height="28" fill="currentColor"><path d="M12 2l2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2z"/></svg></span><strong>{l.title}</strong><span className="te-meta"><span className="sc-tiles" aria-hidden="true">{Array.from({length:Math.min(12,Math.max(l.tasks||0,l.answered))},(_,k)=><i key={k} className={'sc-tile '+(k<l.answered?'is-explore':'is-empty')} style={{'--i':k}}/>)}</span> {l.answered}{l.tasks?' of '+l.tasks:''} tasks answered{l.investigations?` · ${l.investigations} investigation${l.investigations===1?'':'s'}`:''}{l.help?' · help used '+l.help:''}{l.reflection?' · reflection saved':''}</span><small>{when(l.updated)}</small></li>)}</ul></section>}
 {free.length>0&&<section className="surface trail-section"><div className="section-heading"><div><p className="trail-kicker">Free play</p><h2>Games from the library</h2></div></div><p className="subtle">Games you played for fun or practice. They don’t change your assigned course progress.</p><ul className="trail-extra">{free.map((r,i)=>{const o=r.summary.observations.filter(o=>o.attempts>0||o.correct!==null),first=o.filter(o=>o.correct===true&&o.attempts<=1&&!o.assisted).length,help=o.filter(o=>o.assisted).length;const linkable=!String(r.summary.packId).startsWith('generated-');return <li key={r.key} className={linkable?'is-link':''} style={{'--i':i}}><img className="te-art" src={art(r.summary.template,r.summary.packId)} alt=""/><strong>{linkable?<a className="te-link" href={'/modes.html?game='+encodeURIComponent(r.summary.packId)}>{r.summary.title}</a>:r.summary.title}</strong><span className="te-meta">{o.length?<ScoreTiles firstTry={first} answered={o.length} help={help}/>:null}<StatusPill state={r.summary.completed?'done':'doing'}/>{o.length?<span>{first}/{o.length} right first time</span>:null}</span><small>{when(r.updated)}</small>{linkable&&<svg className="te-go" viewBox="0 0 20 20" aria-hidden="true"><path d="M7 4l6 6-6 6" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>}</li>})}</ul></section>}</>;
