import React,{useEffect,useRef,useState} from 'react';
import {pilotRequest} from './client.js';
import {courseDelivery,checkedDelivery,deliverCourse} from './course-delivery.js';
import './course-delivery.css';

export function CourseDelivery({course,job,data,client,onReload,onAssigned}){
 const [instructions,setInstructions]=useState(''),[due,setDue]=useState('');
 const [resourceOptions,setResourceOptions]=useState([]),[learningResources,setLearningResources]=useState([]);
 const [bankOptions,setBankOptions]=useState([]),[questionBanks,setQuestionBanks]=useState([]),[bankError,setBankError]=useState('');
 const [selected,setSelected]=useState([]),[busy,setBusy]=useState(false),[error,setError]=useState(''),[receipts,setReceipts]=useState([]),[review,setReview]=useState(false);
 const mounted=useRef(true),running=useRef(false),identity=client.journal.user.id;
 useEffect(()=>{mounted.current=true;return()=>{mounted.current=false}},[]);
 const delivery=courseDelivery(course,job,data.chapters);
 useEffect(()=>{let active=true;setQuestionBanks([]);setBankOptions([]);setLearningResources([]);setResourceOptions([]);setBankError('');setReview(false);if(delivery.ready)client.journal.request('course-sharing?'+new URLSearchParams({view:'questions',courseId:course.id,planHash:job.draftHash})).then(v=>{if(active){setBankOptions(v.steps);setResourceOptions(v.learningResources||[])}}).catch(e=>{if(active)setBankError(e.message)});return()=>{active=false}},[delivery.fingerprint]);
 const latest=useRef(delivery.fingerprint);latest.current=delivery.fingerprint;
 const current=()=>mounted.current&&client.journal.user?.id===identity&&latest.current===delivery.fingerprint;
 const learners=(client.access?.roster||[]).filter(m=>m.role==='learner'&&m.status==='active'&&m.manager===client.access.accountReference);
 const confirmed=receipts.filter(r=>r.status==='confirmed').length,complete=receipts.length>0&&confirmed===receipts.length;
 async function send(){
  if(running.current)return;running.current=true;setBusy(true);setError('');
  try{
   // A stale tab must not send yesterday's plan or roster. Server still checks
   // every individual grant, including content changed during this batch.
   const [notebook,plans,people]=await Promise.all([client.journal.request('courses'),client.journal.request('course-plan?'+new URLSearchParams({courseId:course.id})),pilotRequest()]);
   if(!current())return;
   const checked=checkedDelivery({courseId:course.id,planId:job.id,fingerprint:delivery.fingerprint,selected},{notebook,plans,people});
   const existing=await client.journal.request('course-sharing?'+new URLSearchParams({view:'delivery',courseId:course.id,learners:selected.join(',')}));
   if(!current())return;
   const tasks=[...new Set(checked.map(t=>t.learner))].map(learner=>({key:JSON.stringify([learner,course.id,job.draftHash,questionBanks,learningResources,instructions,due]),learner,label:learners.find(l=>l.accountReference===learner)?.label||'Learner',title:course.title,status:'pending',body:{action:'assign',learner,courseId:course.id,planHash:job.draftHash,questionBanks,learningResources,settings:{instructions,dueAt:due?new Date(due).getTime():null},expectedRevision:existing.assignments.find(a=>a.learner===learner)?.revision||null}}));
   const result=await deliverCourse({tasks,previous:receipts,send:b=>client.journal.request('course-sharing',b),isCurrent:current,onUpdate:setReceipts});
   if(current())onAssigned?.();
   if(current())setReceipts(result);
  }catch(e){if(current())setError(e.message)}finally{running.current=false;if(mounted.current&&client.journal.user?.id===identity)setBusy(false)}
 }
 return <section className="course-delivery" aria-label="Course delivery"><header><div><span className="cd-eyebrow">SHARE THE REVIEWED ACTIVITIES</span><h4>Ready for your learners?</h4></div><p className="cd-count"><strong>{delivery.steps.filter(s=>s.ready).length}</strong> / {delivery.steps.length} objectives ready</p></header>
 <p>{delivery.reason}</p>{onReload&&<button disabled={busy} onClick={async()=>{if(running.current)return;running.current=true;setBusy(true);setError('');try{await onReload()}catch(e){if(current())setError(e.message)}finally{running.current=false;if(mounted.current&&client.journal.user?.id===identity)setBusy(false)}}}>Reload course and learner list</button>}
 <ol className="cd-readiness">{delivery.steps.map(s=><li key={s.id}><span>{s.objective}</span><b className={s.ready?'cd-ready':'cd-waiting'}>{s.reason}</b></li>)}</ol>
 {delivery.ready&&<fieldset disabled={busy||receipts.length>0}><legend>Connected learning package</legend><p>Attach an Explore lesson, a question cycle, a podcast and a cartoon to the same objective. Each selected version is frozen for this assignment. Learners can choose which formats to use. Episodes share their reviewed scripts and any saved narration; this does not generate audio.</p>{delivery.steps.map(step=>{const choice=learningResources.find(r=>r.objectiveId===step.id);return <div key={step.id} className="connected-choices"><h3>{step.objective}</h3><label className="check"><input type="checkbox" checked={!!choice} onChange={e=>{setLearningResources(v=>[...v.filter(r=>r.objectiveId!==step.id),...(e.target.checked?[{objectiveId:step.id,resources:[]}]:[])]);setReview(false)}}/>Replace this objective’s package with the selections below</label>{choice?['explore','practice','podcast','cartoon'].map(kind=><label key={kind}>{({explore:'Explore lesson',practice:'Question cycle',podcast:'Podcast',cartoon:'Cartoon'})[kind]}<select value={choice.resources.find(r=>r.kind===kind)?.id||''} onChange={e=>{const r=resourceOptions.find(o=>o.objectiveId===step.id)?.resources.find(r=>r.id===e.target.value);setLearningResources(v=>v.map(c=>c.objectiveId===step.id?{...c,resources:[...c.resources.filter(x=>x.kind!==kind),...(r?[{id:r.id,hash:r.hash,kind}]:[])]}:c));setReview(false)}}><option value="">No resource of this format</option>{resourceOptions.find(o=>o.objectiveId===step.id)?.resources.filter(r=>r.kind===kind).map(r=><option key={r.id} value={r.id}>{r.title}</option>)}</select></label>):<p>Keep an existing package for an unchanged chapter.</p>}</div>})}</fieldset>}
 {delivery.ready&&<fieldset disabled={busy||receipts.length>0}><legend>Optional reviewed learning activities</legend><p className="cd-note">Choose either a four-question learning cycle or an Explore lesson with richer practice for each objective. The default keeps each learner’s existing set for an unchanged chapter, including when reassigning a withdrawn course. Changed chapters need a new selection. A new selection freezes this reviewed version. To deliver later edits, select the new version and reassign; withdraw a course to stop access. Learner answers stay private.</p>{bankError&&<p role="alert">{bankError} You can still assign the games without question sets.</p>}{delivery.steps.map(step=><label key={step.id}>{step.objective}<select aria-label={'Learning activity for '+step.objective} value={questionBanks.find(q=>q.objectiveId===step.id)?.id||(questionBanks.find(q=>q.objectiveId===step.id)?.remove?'remove':'')} onChange={e=>{const q=bankOptions.find(s=>s.objectiveId===step.id)?.banks.find(b=>b.id===e.target.value);setQuestionBanks(v=>[...v.filter(b=>b.objectiveId!==step.id),...(q?[{objectiveId:step.id,id:q.id,hash:q.hash}]:e.target.value==='remove'?[{objectiveId:step.id,remove:true}]:[])]);setReview(false)}}><option value="">Keep set for unchanged chapter · otherwise game only</option><option value="remove">Remove questions · keep the game</option>{bankOptions.find(s=>s.objectiveId===step.id)?.banks.map(b=><option key={b.id} value={b.id}>{b.title} · {b.kind==='explore'?'Explore lesson':b.questions+' questions'} · {b.hash.slice(0,8)}</option>)}</select></label>)}</fieldset>}
 <fieldset disabled={busy||receipts.length>0}><legend>Assignment instructions and timing</legend><label>Instructions for your learners<textarea maxLength={1200} value={instructions} onChange={e=>{setInstructions(e.target.value);setReview(false)}}/></label><label>Suggested due date · your local time<input type="datetime-local" value={due} onInput={e=>{setDue(e.currentTarget.value);setReview(false)}} onChange={e=>{setDue(e.target.value);setReview(false)}} onBlur={e=>{if(e.currentTarget.value!==due){setDue(e.currentTarget.value);setReview(false)}}}/></label><p>Late work remains available. Learners retain their own accessibility settings. Assignments are formative practice, not timed examinations.</p></fieldset>
 <p className="cd-note">Each learner receives the exact published activities in their assigned learning shelf. Your personal plan context, source library and private answers stay private. Learners receive a saved course route and choose whether to share their own status or help requests. Sending a changed course version replaces the previous assignment and turns sharing off for that new version.</p>
 {delivery.ready&&<><fieldset disabled={busy||receipts.length>0}><legend>Choose learners · up to 20 per delivery</legend>{learners.length?<div className="cd-learners">{learners.map(m=><label className="check" key={m.accountReference}><input type="checkbox" checked={selected.includes(m.accountReference)} disabled={!selected.includes(m.accountReference)&&selected.length>=20} onChange={e=>{setSelected(v=>e.target.checked?[...v,m.accountReference]:v.filter(id=>id!==m.accountReference));setReview(false)}}/><span><b>{m.label||'Learner '+m.accountReference.slice(0,8)}</b>{m.group&&<small>{m.group}</small>}</span></label>)}</div>:<p>No active learners in your group. <a href="/welcome.html">Invite learners</a> before assigning.</p>}</fieldset>
 {!receipts.length&&<label className="check cd-confirm"><input type="checkbox" checked={review} disabled={busy||!selected.length} onChange={e=>setReview(e.target.checked)}/>I checked the objectives, published activities, selected question sets and learners.</label>}
 <div className="cd-actions"><button className="primary" disabled={busy||complete||!selected.length||!review} onClick={send}>{busy?'Assigning activities…':complete?'All deliveries confirmed':receipts.length?'Retry unconfirmed deliveries':'Assign course activities'}</button>{receipts.length>0&&!busy&&<button onClick={()=>{setReceipts([]);setSelected([]);setReview(false);setError('')}}>Choose another group</button>}</div><ClassDelivery client={client} course={course} job={job} locked={busy} body={{questionBanks,learningResources,settings:{instructions,dueAt:due?new Date(due).getTime():null}}}/></>}
 <div className="cd-results" aria-live="polite">{error&&<p className="message error" role="alert">{error}</p>}{receipts.length>0&&<><p><b>{confirmed} of {receipts.length} deliveries confirmed.</b> {complete?'Learners can open the activities in Studio.':busy?'Keep this course open while delivery finishes.':'Delivery stopped. Confirmed courses stay assigned. You can retry the remaining items.'}</p><p className="cd-note">These receipts last while this course view is open. An unconfirmed request may have reached the server; retrying the same version safely replaces the same assignment.</p><ul>{receipts.map(r=><li key={r.key}><div><b>{r.label}</b><span>{r.title}</span></div><span>{r.status==='confirmed'?'Confirmed':r.status==='pending'?'Not sent':'Unconfirmed'}</span>{r.error&&<p role="alert">{r.error}</p>}</li>)}</ul></>}</div>
 </section>;
}

// Whole-class delivery: the server assigns each class member the same reviewed
// version and reports who received it, who already had it, and who was skipped.
export function ClassDelivery({client,course,job,body,locked}){
 const [classes,setClasses]=useState(null),[classId,setClassId]=useState(''),[ok,setOk]=useState(false),[busy,setBusy]=useState(false),[results,setResults]=useState([]),[error,setError]=useState(''),[done,setDone]=useState(false);
 useEffect(()=>{let live=true;client.journal.request('classes').then(d=>{if(live)setClasses((d.teaching||[]).filter(c=>!c.archived))}).catch(()=>{if(live)setClasses([])});return()=>{live=false}},[]);
 if(!classes)return null;
 if(!classes.length)return <p className="cd-note cd-class-empty">Teach a class? Create one in Classes and you can assign this course to everyone in it at once.</p>;
 async function send(){
  setBusy(true);setError('');setResults([]);setDone(false);
  try{let cursor=null,all=[];do{const r=await client.journal.request('course-sharing',{action:'assign-class',classId,courseId:course.id,planHash:job.draftHash,...body,...(cursor?{cursor}:{})});all=[...all,...r.results];setResults(all);cursor=r.nextCursor}while(cursor);setDone(true)}
  catch(e){setError(e.message)}finally{setBusy(false)}
 }
 const count=k=>results.filter(r=>r.status===k).length,label={assigned:'Assigned',unchanged:'Already has this version',kept:'Kept their own version',skipped:'Not assigned'};
 return <fieldset className="cd-class" disabled={locked||busy}><legend>Or assign to a whole class</legend>
  <p>Everyone in the class gets the same reviewed version, activities, instructions and due date chosen above. Send again to reach learners who join later; anyone who already has this version is left as is. A changed version replaces what this class was sent before and turns sharing off for it, so learners choose again. Learners in your group keep any version you assigned to them individually. Leaving the class ends a class assignment.</p>
  <label>Class<select value={classId} onChange={e=>{setClassId(e.target.value);setOk(false);setResults([]);setDone(false)}}><option value="">Choose a class</option>{classes.map(c=><option key={c.id} value={c.id}>{c.name} · {c.learners} {c.learners===1?'learner':'learners'}</option>)}</select></label>
  <label className="check"><input type="checkbox" checked={ok} disabled={!classId} onChange={e=>setOk(e.target.checked)}/>I checked the objectives, activities and class.</label>
  <div className="cd-actions"><button className="primary" disabled={!classId||!ok||busy} onClick={send}>{busy?'Assigning to the class…':done?'Send again':'Assign to class'}</button></div>
  <div className="cd-results" aria-live="polite">{error&&<p className="message error" role="alert">{error}</p>}
  {results.length>0&&<><p><b>{count('assigned')} assigned · {count('unchanged')} already had it{count('kept')?' · '+count('kept')+' kept their own version':''} · {count('skipped')} not assigned.</b>{busy?' Keep this course open while the class is assigned.':''}</p>
  <ul>{results.map((r,i)=><li key={i}><div><b>{r.label}</b>{r.reason&&<span>{r.reason}</span>}</div><span className={'cd-status is-'+r.status}>{label[r.status]}</span></li>)}</ul></>}</div>
 </fieldset>;
}
