import React,{useEffect,useRef,useState} from 'react';
import {LibraryPicker} from './SourceLibrary.jsx';
export function SourceCollections({client}){
 const [data,setData]=useState(null),[active,setActive]=useState(null),[draft,setDraft]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[confirm,setConfirm]=useState(false);const lock=useRef(false),life=useRef(true);
 const call=body=>client.journal.request('collections',body),reload=async()=>{const d=await call();if(life.current)setData(d)};
 const run=async fn=>{if(lock.current)return;lock.current=true;setBusy(true);setError('');try{await fn()}catch(e){if(life.current)setError(e.message)}finally{lock.current=false;if(life.current)setBusy(false)}};
 useEffect(()=>{life.current=true;void run(reload);return()=>{life.current=false}},[]);
 const open=async(id,sourceId)=>{const d=await client.journal.request('collections?'+new URLSearchParams({id,...(sourceId?{sourceId}:{})}));if(life.current){setActive(d.collection);setDraft(null);setConfirm(false)}};
 const edit=c=>{setDraft(c?{id:c.id,revision:c.revision,title:c.title,description:c.description,sources:c.sources.filter(r=>r.available).map(({id,checksum,title})=>({id,checksum,title})),readers:c.readers||[]}:{title:'',description:'',sources:[],readers:[]});setConfirm(false)};
 const roster=(client.access?.roster||[]).filter(m=>m.status==='active'&&m.manager===client.access.accountReference);
 return <section className="surface source-collections"><div className="section-heading"><div><h2>Curated collections</h2><p>Gather reviewed versions for a topic or learning group.</p></div>{data?.canCreate&&<button disabled={busy} onClick={()=>edit(null)}>New collection</button>}</div>{busy&&<p role="status">Opening your collections…</p>}{error&&<p role="alert" className="message error">{error}</p>}
 {!draft&&!active&&<>{!data?.collections.length&&<p>No collections yet. Shared collections will appear here when your organiser gives you access.</p>}{data?.collections.map(c=><div className="source-version" key={c.id}><div><h3>{c.title}</h3><p>{c.description}</p><small>{c.count} reviewed source versions · {c.canEdit?'You curate this':'Shared with you'}</small></div><button disabled={busy} onClick={()=>run(()=>open(c.id))}>Open collection</button></div>)}</>}
 {!draft&&active&&<><button disabled={busy} onClick={()=>setActive(null)}>All collections</button><h3>{active.title}</h3><p>{active.description}</p>{active.canEdit&&<button disabled={busy} onClick={()=>edit(active)}>Edit sources and access</button>}{active.sources.map(s=><article className="source-passage" key={s.id}><h3>{s.title}</h3>{s.available?<><button disabled={busy} onClick={()=>run(()=>open(active.id,s.id))}>Read reviewed passages</button>{s.units?.map(u=><div key={u.id}><h4>{u.locator}</h4><p>{u.excerpt}</p></div>)}</>:<p>This exact source version is unavailable. Ask the curator for a reviewed replacement.</p>}</article>)}</>}
 {draft&&<><label>Collection title<input maxLength={160} value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})}/></label><label>Purpose and scope<textarea maxLength={1000} rows={3} value={draft.description} onChange={e=>setDraft({...draft,description:e.target.value})}/></label><h3>Reviewed sources ({draft.sources.length}/50)</h3>{draft.sources.map(s=><div className="source-version" key={s.id}><span>{s.title}</span><button disabled={busy} aria-label={'Remove '+s.title} onClick={()=>setDraft({...draft,sources:draft.sources.filter(r=>r.id!==s.id)})}>Remove</button></div>)}<details><summary>Add from my source library</summary><LibraryPicker linked={draft.sources.map(s=>s.id)} disabled={busy||draft.sources.length>=50} actionLabel="Add reviewed source" onPick={r=>{if(r.status!=='reviewed'){setError('Review this source before adding it to a collection.');return}setDraft({...draft,sources:[...draft.sources,{id:r.id,title:r.title,checksum:r.checksum}]});setError('')}}/></details><h3>Who can read this collection?</h3><p>Keep it private, or select active people in your existing learning group. Readers receive reviewed text, not original files or authoring access.</p>{roster.map(m=><label className="check" key={m.accountReference}><input type="checkbox" checked={draft.readers.includes(m.accountReference)} onChange={e=>{setDraft({...draft,readers:e.target.checked?[...draft.readers,m.accountReference]:draft.readers.filter(id=>id!==m.accountReference)});setConfirm(false)}}/>{m.label||'Group member'}</label>)}{draft.readers.filter(id=>!roster.some(m=>m.accountReference===id)).map(id=><label className="check" key={id}><input type="checkbox" checked onChange={()=>{setDraft({...draft,readers:draft.readers.filter(v=>v!==id)});setConfirm(false)}}/>Unavailable former group member — uncheck to remove this saved recipient</label>)}{!roster.length&&<p>No active group members are available. This collection stays private.</p>}{draft.readers.length>0&&<label className="check"><input type="checkbox" checked={confirm} onChange={e=>setConfirm(e.target.checked)}/>I have permission to share these exact sources with the selected people.</label>}<div className="form-actions"><button className="primary" disabled={busy||!draft.title.trim()||draft.readers.length>0&&!confirm} onClick={()=>run(async()=>{const saved=await call({action:'save',...draft,sharingConfirmed:confirm});await reload();await open(saved.id)})}>Save collection</button><button disabled={busy} onClick={()=>setDraft(null)}>Cancel edits</button>{draft.id&&<button disabled={busy} onClick={()=>run(async()=>{await call({action:'delete',id:draft.id,revision:draft.revision});setActive(null);setDraft(null);await reload()})}>Remove collection and access</button>}</div><p>Removing a collection withdraws its shared view; it keeps the sources in your library.</p></>}
 </section>;
}
